/**
 * src/ai/utils/github-app/files.ts
 * Read, write, and update files in GitHub repositories.
 */

import { getInstallationAccessToken } from "./auth";
import { request } from "@octokit/request";

/**
 * Reads the content of a file from a repo.
 */
export async function readFile(
  installationId: number,
  owner: string,
  repo: string,
  path: string,
  ref = "main"
): Promise<string> {
  const token = await getInstallationAccessToken(installationId);
  const response = await request("GET /repos/{owner}/{repo}/contents/{path}", {
    owner,
    repo,
    path,
    ref,
    headers: { authorization: `token ${token}` },
  });

  // Type guard: ensure we're dealing with a file, not a directory or array
  if (Array.isArray(response.data)) {
    throw new Error(`Path ${path} is a directory, not a file`);
  }
  if (!('content' in response.data)) {
    throw new Error(`No content found for ${path}`);
  }

  return Buffer.from(response.data.content, "base64").toString("utf-8");
}

/**
 * Writes a file (create or update) with commit message.
 */
export async function writeFile(
  installationId: number,
  owner: string,
  repo: string,
  path: string,
  message: string,
  content: string,
  sha?: string,
  branch = "main"
) {
  const token = await getInstallationAccessToken(installationId);
  const encoded = Buffer.from(content).toString("base64");

  const params: any = {
    owner,
    repo,
    path,
    message,
    content: encoded,
    branch,
    headers: { authorization: `token ${token}` },
  };
  if (sha) params.sha = sha;

  const response = await request("PUT /repos/{owner}/{repo}/contents/{path}", params);
  return response.data;
}

/**
 * Retrieves the SHA for a file in the repo.
 */
export async function getFileSha(
  installationId: number,
  owner: string,
  repo: string,
  path: string,
  ref = "main"
): Promise<string | null> {
  try {
    const token = await getInstallationAccessToken(installationId);
    const response = await request("GET /repos/{owner}/{repo}/contents/{path}", {
      owner,
      repo,
      path,
      ref,
      headers: { authorization: `token ${token}` },
    });

    // Type guard: ensure we're dealing with a file, not a directory or array
    if (Array.isArray(response.data)) {
      throw new Error(`Path ${path} is a directory, not a file`);
    }

    return response.data.sha;
  } catch (error: any) {
    if (error.status === 404) return null;
    throw error;
  }
}

/**
 * File: src/ai/core_reasoning/symbolicLogicParser.ts
 * Description: Very small symbolic logic expression parser (supports AND/OR/NOT parentheses).
 */

export const parseBooleanExpr = (expr: string): ((vars: Record<string, boolean>) => boolean) => {
  // This is a fragile, tiny parser for demo use only.
  return (_vars: Record<string, boolean>) => {
    // replace variable names with a lookup access placeholder; in a full impl you'd substitute safely
    const safe = expr.replace(/([a-zA-Z_][a-zA-Z0-9_]*)/g, (m) => `(_vars['${m}'])`);
    const finalExpr = safe
      .replace(/\band\b/gi, '&&')
      .replace(/\bor\b/gi, '||')
      .replace(/\bnot\b/gi, '!');
    return Boolean(eval(finalExpr));
  };
};

