export const buildAlgorithmsTokenMap = () => {
  const map = new Map<string, number>()
  let id = 0
  map.set("[PAD]", id++)
  map.set("[UNK]", id++)
  map.set("[CLS]", id++)
  for (const t of ALGORITHMS_CORE_TOKENS) {
    if (!map.has(t)) map.set(t, id++)
  }
  return map
}

