  algorithmsTokenMap.get(token) ?? algorithmsTokenMap.get("[UNK]")!
export const getAlgorithmsTokenById = (id: number): string | undefined => {
  for (const [k, v] of algorithmsTokenMap.entries()) if (v === id) return k
