/**
 * File: src/ai/data/dataRegistry.ts
 * Purpose: Track files that belong to knowledge domains, provide safe write/update APIs,
 * and publish change events on the orchestration event bus.
 * Depends on: src/ai/orchestration/eventBus.ts
 * Depended on by: src/ai/orchestration/aiOrchestrator.ts, domain integration APIs
 * Creator: Vercel v0 Coding Assistant
 */

import { publish } from "../orchestration/eventBus"

type FileRecord = { path: string; lastModified: number; content?: string }

const domainFiles = new Map<string, FileRecord[]>()
const fileContents = new Map<string, string>()

const safeNow = () => Date.now()

/**
 * Register a list of file paths as belonging to a domain.
 * Publishes a "data:registered" event.
 */
export function registerDomainFiles(domain: string, files: string[]): void {
  const records = files.map((p) => ({ path: p, lastModified: safeNow() }))
  domainFiles.set(domain, records)
  publish("data:registered", { domain, files: records })
}

/**
 * List all registered files for a domain, or all domains if no domain specified.
 */
export function listDomainFiles(domain?: string): Record<string, FileRecord[]> | FileRecord[] {
  if (!domain) {
    const out: Record<string, FileRecord[]> = {}
    for (const [k, v] of domainFiles.entries()) out[k] = v
    return out
  }
  return domainFiles.get(domain) ?? []
}

/**
 * Get metadata for a specific file in a domain.
 */
export function getFileRecord(domain: string, filePath: string): FileRecord | null {
  const files = domainFiles.get(domain) ?? []
  return files.find((f) => f.path === filePath) ?? null
}

/**
 * Safely write content to a file and update the registry.
 * Publishes a "data:changed" event on success or "data:error" on failure.
 */
export function updateFile(domain: string, filePath: string, content: string): boolean {
  try {
    fileContents.set(filePath, content)

    const recs: FileRecord[] = domainFiles.get(domain) ?? []
    const idx = recs.findIndex((r) => r.path === filePath)
    const now = safeNow()
    if (idx >= 0) {
      recs[idx].lastModified = now
    } else {
      recs.push({ path: filePath, lastModified: now })
    }
    domainFiles.set(domain, recs)

    publish("data:changed", { domain, file: filePath, action: "updated", timestamp: now })
    return true
  } catch (e) {
    publish("data:error", { domain, file: filePath, error: e })
    return false
  }
}

/**
 * Read file content safely.
 */
export function readFile(filePath: string, domain?: string): string | null {
  try {
    const content = fileContents.get(filePath)
    if (content !== undefined) {
      publish("data:read", { domain, file: filePath, timestamp: safeNow() })
      return content
    }
    return null
  } catch (e) {
    return null
  }
}

/**
 * Watch domain files for changes (placeholder for future implementation).
 */
export function watchDomainFiles(domain: string): boolean {
  const files = domainFiles.get(domain) ?? []
  publish("data:watching", { domain, count: files.length })
  return false
}

export default {
  registerDomainFiles,
  listDomainFiles,
  getFileRecord,
  updateFile,
  readFile,
  watchDomainFiles,
}

/**
 * Data Integrity Domain Inference Controller
 * Handles data validation, consistency checks, and data quality queries
 */

import { DOMAIN_NAME } from './data_integrity_constants';

export const dataIntegrityRunInference = async (input: string, _context?: any) => {
  const lowerInput = input.toLowerCase();

  let responseText = '';
  let confidence = 0.7;
  const sources: string[] = [];

  // Detect data integrity keywords
  if (
    lowerInput.includes('data') ||
    lowerInput.includes('valid') ||
    lowerInput.includes('integrity') ||
    lowerInput.includes('consistency') ||
    lowerInput.includes('quality') ||
    lowerInput.includes('corrupt')
  ) {
    confidence = 0.85;

    responseText = `I can help with data integrity and validation. Key concepts:

**Data Validation:**
- Input validation and sanitization
- Schema validation (JSON Schema, Zod, Yup)
- Type checking and constraints
- Format validation (emails, URLs, dates)

**Data Consistency:**
- Database constraints (primary keys, foreign keys)
- Transaction management (ACID properties)
- Data synchronization
- Conflict resolution

**Data Quality:**
- Completeness checks
- Accuracy verification
- Uniqueness constraints
- Timeliness validation

What specific data integrity topic would you like to explore?`;
  } else {
    responseText = `I'm the Data Integrity domain. I specialize in:
- Data validation strategies
- Consistency checking
- Quality assurance
- Error detection in data
- Data cleaning and normalization

How can I help you ensure data integrity?`;
  }

  return {
    text: responseText,
    confidence,
    sources,
    domain: DOMAIN_NAME,
  };
};

export default dataIntegrityRunInference;

/**
 * Data Integrity Domain Integration API
 * 
 * Handles data validation, consistency checks, quality assurance, and error detection.
 * Ensures data reliability and integrity across the system.
 */

import { domainRegistry } from '../domainRegistry';
import fs from 'fs/promises';
import path from 'path';

const DOMAIN_NAME = 'data_integrity';
const DOMAIN_DIR = path.join(process.cwd(), 'src', 'ai', 'knowledge-domains', DOMAIN_NAME);
const SEEDS_DIR = path.join(DOMAIN_DIR, `${DOMAIN_NAME}_seeds`);

/**
 * Load all seed data for data integrity domain
 */
async function loadSeedData(): Promise<any[]> {
  try {
    const files = await fs.readdir(SEEDS_DIR);
    const jsonFiles = files.filter(f => f.endsWith('.json'));

    const allConcepts: any[] = [];
    for (const file of jsonFiles) {
      const filePath = path.join(SEEDS_DIR, file);
      const content = await fs.readFile(filePath, 'utf-8');
      const data = JSON.parse(content);

      // Handle both {concepts: [...]} and direct array formats
      if (data.concepts && Array.isArray(data.concepts)) {
        allConcepts.push(...data.concepts);
      } else if (Array.isArray(data)) {
        allConcepts.push(...data);
      }
    }

    console.log(`[DataIntegrity] Loaded ${allConcepts.length} concepts from ${jsonFiles.length} seed files`);
    return allConcepts;
  } catch (error) {
    console.error('[DataIntegrity] Error loading seed data:', error);
    return [];
  }
}

/**
 * Query the data integrity domain with a prompt
 */
async function query(prompt: string): Promise<any> {
  const normalizedPrompt = prompt.toLowerCase();

  // Keywords that indicate data integrity concerns
  const integrityKeywords = [
    'validate', 'validation', 'verify', 'check', 'integrity', 'quality',
    'consistency', 'accuracy', 'completeness', 'constraint', 'error',
    'duplicate', 'missing', 'corrupt', 'anomaly', 'outlier'
  ];

  const hasIntegrityKeyword = integrityKeywords.some(keyword => 
    normalizedPrompt.includes(keyword)
  );

  if (!hasIntegrityKeyword) {
    return null;
  }

  const seedData = await loadSeedData();

  // Find matching concepts
  const matches = seedData.filter(concept => {
    const conceptText = JSON.stringify(concept).toLowerCase();
    return integrityKeywords.some(keyword => conceptText.includes(keyword));
  });

  if (matches.length === 0) {
    return null;
  }

  return {
    domain: DOMAIN_NAME,
    confidence: 0.8,
    matches: matches.slice(0, 5), // Return top 5 matches
    suggestion: 'Consider data validation rules, consistency checks, and quality metrics',
    metadata: {
      totalConcepts: seedData.length,
      matchCount: matches.length
    }
  };
}

