import pretrained from "./documentation_weights/documentation_pretrained_weights.json"
import { DOCUMENTATION_DOMAIN } from "./documentation_constants"
import { updateFile } from "../dataRegistry"

const p = pretrained as Record<string, unknown>
const EMBEDDING_DIM = typeof p.embeddingDim === "number" ? (p.embeddingDim as number) : 128

const seededVector = (s: string, dim = EMBEDDING_DIM) => {
  const out: number[] = new Array(dim).fill(0).map((_, i) => {
    let h = 2166136261 >>> 0
    for (let j = 0; j < s.length; j++) h = Math.imul(h ^ s.charCodeAt(j), 16777619) >>> 0
    const v = ((h >> (i % 24)) & 0xffff) / 0xffff
    return (v - 0.5) * 0.4
  })
  return out
}

export const getDocumentationEmbedding = (token: string): number[] => {
  const seed = (p.seedWeights ?? {}) as Record<string, number[]>
  if (Object.prototype.hasOwnProperty.call(seed, token)) return seed[token]
  return seededVector(token, EMBEDDING_DIM)
}

export const getDocumentationEmbeddingForTokens = (tokens: string[]) => tokens.map(getDocumentationEmbedding)

export const persistDocumentationWeights = (weights: Record<string, number[]>) => {
  try {
    const content = JSON.stringify(
      { domain: DOCUMENTATION_DOMAIN, version: "0.2", embeddingDim: EMBEDDING_DIM, seedWeights: weights },
      null,
      2,
    )
    updateFile(DOCUMENTATION_DOMAIN, "src/ai/knowledge-domains/documentation/documentation_weights/documentation_pretrained_weights.json", content)
    return true
  } catch (e) {
    return false
  }
}

