import ENVIRONMENT_CORE_TOKENS from "./environment_tokens"

export const buildEnvironmentTokenMap = () => {
  const map = new Map<string, number>()
  let id = 0
  map.set("[PAD]", id++)
  map.set("[UNK]", id++)
  map.set("[CLS]", id++)
  for (const t of ENVIRONMENT_CORE_TOKENS) {
    if (!map.has(t)) map.set(t, id++)
  }
  return map
}

