  const hasMathSymbols = numericInput.match(/\d+\s*[+\-×x*÷/]\s*\d+/)
  const hasNumbers = lowerInput.match(/\b(one|two|three|four|five|six|seven|eight|nine|ten|eleven|twelve)\b/)
  const hasDigits = numericInput.match(/\d+/)
  const isAIMathQuery =
