class Blockchain {
  private chain: Block[] = [];
  private difficulty = 2;

  constructor() {
    this.chain.push(this.createGenesisBlock());
  }

  private createGenesisBlock(): Block {
    return {
      index: 0,
      timestamp: Date.now(),
      data: "Genesis Block",
      previousHash: "0",
      hash: this.calculateHash(0, Date.now(), "Genesis Block", "0", 0),
      nonce: 0
    };
  }

  private calculateHash(
    index: number,
    timestamp: number,
    data: string,
    previousHash: string,
    nonce: number
  ): string {
    return crypto
      .createHash('sha256')
      .update(index + timestamp + data + previousHash + nonce)
      .digest('hex');
  }

  private mineBlock(block: Block): Block {
    while (block.hash.substring(0, this.difficulty) !== Array(this.difficulty + 1).join("0")) {
      block.nonce++;
      block.hash = this.calculateHash(
        block.index,
        block.timestamp,
        block.data,
        block.previousHash,
        block.nonce
      );
    }
    return block;
  }

  addBlock(data: string): void {
    const previousBlock = this.chain[this.chain.length - 1];
    const newBlock: Block = {
      index: previousBlock.index + 1,
      timestamp: Date.now(),
      data,
      previousHash: previousBlock.hash,
      hash: "",
      nonce: 0
    };

    newBlock.hash = this.calculateHash(
      newBlock.index,
      newBlock.timestamp,
      newBlock.data,
      newBlock.previousHash,
      newBlock.nonce
    );

    this.chain.push(this.mineBlock(newBlock));
  }

  isChainValid(): boolean {
    for (let i = 1; i < this.chain.length; i++) {
      const currentBlock = this.chain[i];
      const previousBlock = this.chain[i - 1];

      if (currentBlock.hash !== this.calculateHash(
        currentBlock.index,
        currentBlock.timestamp,
        currentBlock.data,
        currentBlock.previousHash,
        currentBlock.nonce
      )) {
        return false;
      }

      if (currentBlock.previousHash !== previousBlock.hash) {
        return false;
      }
    }
    return true;
  }
}

