    if (type.includes('create')) return 'bg-green-500/10 text-green-500';
    if (type.includes('delete')) return 'bg-red-500/10 text-red-500';
    if (type.includes('update') || type.includes('save')) return 'bg-blue-500/10 text-blue-500';
