  const getDefaultSettings = (): SystemSettings => ({
    general: {
      systemName: 'ZacAi-Atomic',
      version: '0.0.2',
      environment: 'production',
      maintenanceMode: false,
    },
    ai: {
      maxTokens: 2048,
      temperature: 0.7,
      topP: 0.9,
      frequencyPenalty: 0.0,
      presencePenalty: 0.0,
      streamingEnabled: true,
    },
    security: {
