                  <Input
                    id="version"
                    value={settings.general.version}
                    onChange={(e) => updateSetting('general', 'version', e.target.value)}
                  />
                </div>
              </div>
              <div className="space-y-2">
                <Label htmlFor="environment">Environment</Label>
