    setCurrentUser(user)
    setFormData({ name: user.name, email: user.email, role: user.role })
    setIsEditModalOpen(true)
  }

  const openDeleteModal = (user: User) => {
    setCurrentUser(user)
    setIsDeleteModalOpen(true)
  }

