    switch (role) {
      case "admin": return "default"
      case "system": return "secondary"
      default: return "outline"
    }
  }

  const getRoleIcon = (role: string) => {
    switch (role) {
      case "admin": return "👤"
      case "system": return "🤖"
      default: return "👥"
    }
  }

