/**
 * File: src/app/api/admin/dev-console/files/route.ts
 * Purpose: API route for listing directory contents in ZacAi dev console
 * Security: Admin-only access with path validation
 */

import { NextRequest, NextResponse } from 'next/server';
import { promises as fs } from 'fs';
import path from 'path';
import systemActivityLogger from '@/lib/systemActivityLogger.cjs';

const { logEvent } = systemActivityLogger;

// Base path for file operations (project root)
const BASE_PATH = process.env.ZACAI_CODE_ROOT || process.cwd();

// Validate that requested path is within allowed directory
function validatePath(requestedPath: string): string {
  const normalized = path.normalize(requestedPath);
  const resolved = path.resolve(BASE_PATH, normalized);

  if (!resolved.startsWith(BASE_PATH)) {
    throw new Error('Access denied: Path outside allowed directory');
  }

  return resolved;
}

export async function GET(request: NextRequest) {
  try {
    // TODO: Add proper auth check
    // const session = await getServerSession();
    // if (!session?.user?.isAdmin) {
    //   return NextResponse.json({ error: 'Unauthorized' }, { status: 403 });
    // }

    const searchParams = request.nextUrl.searchParams;
    const requestedPath = searchParams.get('path') || '';

    const fullPath = validatePath(requestedPath);

    // Check if path exists
    const stats = await fs.stat(fullPath);

    if (!stats.isDirectory()) {
      return NextResponse.json(
        { error: 'Path is not a directory' },
        { status: 400 }
      );
    }

    // Read directory contents
    const entries = await fs.readdir(fullPath, { withFileTypes: true });

    const items = await Promise.all(
      entries.map(async (entry) => {
        const itemPath = path.join(fullPath, entry.name);
        const relativePath = path.relative(BASE_PATH, itemPath);

        try {
          const itemStats = await fs.stat(itemPath);

          return {
            name: entry.name,
            path: relativePath,
            type: entry.isDirectory() ? 'directory' : 'file',
            size: itemStats.size,
            modified: itemStats.mtime.toISOString(),
          };
        } catch (error) {
          // Skip items we can't access
          return null;
        }
      })
    );

    // Filter out nulls and sort (directories first, then alphabetically)
    const validItems = items.filter(Boolean).sort((a, b) => {
      if (a!.type !== b!.type) {
        return a!.type === 'directory' ? -1 : 1;
      }
      return a!.name.localeCompare(b!.name);
    });

    logEvent('dev_console.files_listed', {
      path: requestedPath,
      itemCount: validItems.length,
    });

    return NextResponse.json({
      path: requestedPath,
      items: validItems,
    });
  } catch (error) {
    console.error('[dev-console] Error listing files:', error);

    return NextResponse.json(
      {
        error: error instanceof Error ? error.message : 'Failed to list files',
      },
      { status: 500 }
    );
  }
}

/**
 * File: src/app/api/admin/github-app/installations/route.ts
 * Purpose: List GitHub App installations
 * 
 * GET - Retrieve all installations for the GitHub App
 */

import { NextRequest, NextResponse } from "next/server";

export const dynamic = "force-dynamic";

/**
 * GET /api/admin/github-app/installations
 * List all installations of the GitHub App
 */
export async function GET(request: NextRequest) {
  try {
    // Get JWT token from internal endpoint
    const jwtResponse = await fetch(`${process.env.NEXT_PUBLIC_APP_URL || "http://localhost:3000"}/api/admin/github-app/jwt`, {
      method: "POST",
    });

    if (!jwtResponse.ok) {
      const error = await jwtResponse.json();
      return NextResponse.json(
        { error: error.error || "Failed to generate JWT" },
        { status: 500 }
      );
    }

    const { token } = await jwtResponse.json();

    // Fetch installations from GitHub API
    const response = await fetch("https://api.github.com/app/installations", {
      headers: {
        Authorization: `Bearer ${token}`,
        Accept: "application/vnd.github.v3+json",
        "User-Agent": "ZacAI-Atomic",
      },
    });

    if (!response.ok) {
      const errorText = await response.text();
      console.error("GitHub API error:", errorText);
      return NextResponse.json(
        { error: "Failed to fetch installations from GitHub" },
        { status: response.status }
      );
    }

    const installations = await response.json();

    // Transform to our format
    const formatted = installations.map((install: any) => ({
      installationId: install.id.toString(),
      accountLogin: install.account.login,
      accountType: install.account.type,
      installedAt: install.created_at,
      repositories: [], // Will be populated on-demand
      permissions: install.permissions || {},
    }));

    return NextResponse.json(formatted);
  } catch (error) {
    console.error("Failed to get installations:", error);
    return NextResponse.json(
      { error: "Failed to retrieve installations" },
      { status: 500 }
    );
  }
}

/**
 * File: src/app/api/admin/github-app/jwt/route.ts
 * Purpose: Generate GitHub App JWT for authentication
 * 
 * POST - Create a JWT token signed with the app's private key
 */

import { NextRequest, NextResponse } from "next/server";
import jwt from "jsonwebtoken";

export const dynamic = "force-dynamic";

/**
 * POST /api/admin/github-app/jwt
 * Generate a GitHub App JWT token
 */
export async function POST(request: NextRequest) {
  try {
    const appId = process.env.GITHUB_APP_ID;
    const privateKey = process.env.GITHUB_APP_PRIVATE_KEY;

    if (!appId || !privateKey) {
      return NextResponse.json(
        { error: "GitHub App credentials not configured. Set GITHUB_APP_ID and GITHUB_APP_PRIVATE_KEY environment variables." },
        { status: 500 }
      );
    }

    // Format private key (handle both raw and base64-encoded)
    let formattedKey = privateKey;
    if (!privateKey.includes("BEGIN RSA PRIVATE KEY")) {
      try {
        formattedKey = Buffer.from(privateKey, "base64").toString("utf8");
      } catch {
        // If not base64, assume it's already formatted
      }
    }

    // Create JWT (valid for 10 minutes)
    const now = Math.floor(Date.now() / 1000);
    const payload = {
      iat: now - 60, // Issued 60 seconds in the past to account for clock drift
      exp: now + 600, // Expires in 10 minutes
      iss: appId,
    };

    const token = jwt.sign(payload, formattedKey, { algorithm: "RS256" });

    return NextResponse.json({ token, expiresAt: payload.exp });
  } catch (error) {
    console.error("Failed to generate JWT:", error);
    return NextResponse.json(
      { error: "Failed to generate JWT token" },
      { status: 500 }
    );
  }
}

/**
 * File: src/app/api/admin/github-app/repositories/route.ts
 * Purpose: List repositories accessible to a GitHub App installation
 * 
 * GET - Retrieve repositories for a specific installation
 */

import { NextRequest, NextResponse } from "next/server";

export const dynamic = "force-dynamic";

/**
 * GET /api/admin/github-app/repositories?installationId=123
 * List repositories for an installation
 */
export async function GET(request: NextRequest) {
  try {
    const { searchParams } = new URL(request.url);
    const installationId = searchParams.get("installationId");

    if (!installationId) {
      return NextResponse.json(
        { error: "installationId query parameter is required" },
        { status: 400 }
      );
    }

    // Get installation token
    const tokenResponse = await fetch(
      `${process.env.NEXT_PUBLIC_APP_URL || "http://localhost:3000"}/api/admin/github-app/installation-token`,
      {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ installationId }),
      }
    );

    if (!tokenResponse.ok) {
      const error = await tokenResponse.json();
      return NextResponse.json(
        { error: error.error || "Failed to get installation token" },
        { status: 500 }
      );
    }

    const { token } = await tokenResponse.json();

    // Fetch repositories
    const response = await fetch(
      "https://api.github.com/installation/repositories",
      {
        headers: {
          Authorization: `Bearer ${token}`,
          Accept: "application/vnd.github.v3+json",
          "User-Agent": "ZacAI-Atomic",
        },
      }
    );

    if (!response.ok) {
      const errorText = await response.text();
      console.error("GitHub API error:", errorText);
      return NextResponse.json(
        { error: "Failed to fetch repositories from GitHub" },
        { status: response.status }
      );
    }

    const data = await response.json();

    // Transform to our format
    const formatted = data.repositories.map((repo: any) => ({
      id: repo.id,
      name: repo.name,
      fullName: repo.full_name,
      private: repo.private,
      defaultBranch: repo.default_branch,
      htmlUrl: repo.html_url,
      description: repo.description,
    }));

    return NextResponse.json(formatted);
  } catch (error) {
    console.error("Failed to get repositories:", error);
    return NextResponse.json(
      { error: "Failed to retrieve repositories" },
      { status: 500 }
    );
  }
}

/**
 * Chat History API Route
 * Handles CRUD operations for persistent chat history
 * 
 * Endpoints:
 * - GET    /api/chat-history         - List all chats
 * - GET    /api/chat-history?id=xxx  - Get specific chat
 * - POST   /api/chat-history         - Create new chat
 * - PUT    /api/chat-history         - Update chat (add message, rename, etc.)
 * - DELETE /api/chat-history?id=xxx  - Delete chat
 */

import { NextRequest, NextResponse } from 'next/server';
import path from 'path';
import { promises as fs } from 'fs';

const CHAT_HISTORY_DIR = path.join(process.cwd(), 'data', 'chat-history');

// ============================================================================
// Helper Functions
// ============================================================================

async function ensureUserDirectory(userId: string) {
  const userDir = path.join(CHAT_HISTORY_DIR, `user-${userId}`);
  try {
    await fs.mkdir(userDir, { recursive: true });
  } catch (error) {
    // Directory might already exist
  }
  return userDir;
}

async function getChatFilePath(userId: string, chatId: string, folder?: string | null) {
  const userDir = await ensureUserDirectory(userId);
  if (folder) {
    return path.join(userDir, folder, `${chatId}.json`);
  }
  return path.join(userDir, `${chatId}.json`);
}

async function loadChat(userId: string, chatId: string, folder?: string | null) {
  const filePath = await getChatFilePath(userId, chatId, folder);
  const data = await fs.readFile(filePath, 'utf-8');
  const chat = JSON.parse(data);

  // Update last accessed
  chat.metadata.lastAccessed = new Date().toISOString();
  await saveChat(userId, chat);

  return chat;
}

async function saveChat(userId: string, chat: any) {
  const filePath = await getChatFilePath(userId, chat.id, chat.folder);
  const dirPath = path.dirname(filePath);

  await fs.mkdir(dirPath, { recursive: true });

  chat.metadata.updatedAt = new Date().toISOString();
  chat.metadata.messageCount = chat.messages.length;

  await fs.writeFile(filePath, JSON.stringify(chat, null, 2), 'utf-8');
}

async function listChats(userId: string, options: any = {}) {
  const { folder = null, sortBy = 'lastAccessed', order = 'desc' } = options;
  const userDir = await ensureUserDirectory(userId);
  const searchDir = folder ? path.join(userDir, folder) : userDir;

  const chats: any[] = [];

  try {
    const files = await getAllChatFiles(searchDir);

    for (const filePath of files) {
      try {
        const data = await fs.readFile(filePath, 'utf-8');
        const chat = JSON.parse(data);

        chats.push({
          id: chat.id,
          title: chat.title,
          folder: chat.folder,
          messageCount: chat.metadata.messageCount,
          createdAt: chat.metadata.createdAt,
          updatedAt: chat.metadata.updatedAt,
          lastAccessed: chat.metadata.lastAccessed,
          domains: chat.metadata.domains,
          preview: chat.messages[chat.messages.length - 1]?.content?.substring(0, 100) || '',
        });
      } catch (error) {
        console.error('Error loading chat:', filePath, error);
      }
    }
  } catch (error) {
    // Directory doesn't exist yet
    return [];
  }

  // Sort
  chats.sort((a, b) => {
    const aVal = a[sortBy];
    const bVal = b[sortBy];
    return order === 'desc' ? (bVal > aVal ? 1 : -1) : (aVal > bVal ? 1 : -1);
  });

  return chats;
}

async function getAllChatFiles(dir: string): Promise<string[]> {
  const files: string[] = [];

  try {
    const entries = await fs.readdir(dir, { withFileTypes: true });

    for (const entry of entries) {
      const fullPath = path.join(dir, entry.name);

      if (entry.isDirectory()) {
        files.push(...await getAllChatFiles(fullPath));
      } else if (entry.name.endsWith('.json') && entry.name.startsWith('chat-')) {
        files.push(fullPath);
      }
    }
  } catch (error) {
    // Directory doesn't exist
  }

  return files;
}

// ============================================================================
// API Handlers
// ============================================================================

export async function GET(request: NextRequest) {
  try {
    const { searchParams } = new URL(request.url);
    const chatId = searchParams.get('id');
    const folder = searchParams.get('folder');
    const userId = searchParams.get('userId') || 'aiascended-001';

    if (chatId) {
      // Get specific chat
      const chat = await loadChat(userId, chatId, folder);
      return NextResponse.json({ success: true, data: chat });
    } else {
      // List all chats
      const sortBy = searchParams.get('sortBy') || 'lastAccessed';
      const order = searchParams.get('order') || 'desc';

      const chats = await listChats(userId, { folder, sortBy, order });
      return NextResponse.json({ success: true, data: chats });
    }
  } catch (error: any) {
    console.error('[Chat History API] GET error:', error);
    return NextResponse.json(
      { success: false, error: error.message },
      { status: 500 }
    );
  }
}

export async function POST(request: NextRequest) {
  try {
    const body = await request.json();
    const { title = 'New Chat', folder = null, userId = 'aiascended-001' } = body;

    const chatId = `chat-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
    const timestamp = new Date().toISOString();

    const chat = {
      id: chatId,
      title,
      folder,
      userId,
      messages: [],
      metadata: {
        createdAt: timestamp,
        updatedAt: timestamp,
        lastAccessed: timestamp,
        messageCount: 0,
        domains: [],
        tags: [],
      },
    };

    await saveChat(userId, chat);

    return NextResponse.json({ success: true, data: chat });
  } catch (error: any) {
    console.error('[Chat History API] POST error:', error);
    return NextResponse.json(
      { success: false, error: error.message },
      { status: 500 }
    );
  }
}

export async function PUT(request: NextRequest) {
  try {
    const body = await request.json();
    const { chatId, folder, userId = 'aiascended-001', action, data } = body;

    if (!chatId) {
      return NextResponse.json(
        { success: false, error: 'chatId is required' },
        { status: 400 }
      );
    }

    const chat = await loadChat(userId, chatId, folder);

    switch (action) {
      case 'addMessage':
        const messageWithMeta = {
          id: `msg-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
          ...data,
          timestamp: new Date().toISOString(),
        };
        chat.messages.push(messageWithMeta);

        if (data.domain && !chat.metadata.domains.includes(data.domain)) {
          chat.metadata.domains.push(data.domain);
        }
        break;

      case 'updateTitle':
        chat.title = data.title;
        break;

      case 'moveToFolder':
        // Delete old file
        const oldPath = await getChatFilePath(userId, chatId, chat.folder);
        try {
          await fs.unlink(oldPath);
        } catch (error) {
          // File might not exist
        }
        chat.folder = data.folder;
        break;

      default:
        return NextResponse.json(
          { success: false, error: 'Invalid action' },
          { status: 400 }
        );
    }

    await saveChat(userId, chat);

    return NextResponse.json({ success: true, data: chat });
  } catch (error: any) {
    console.error('[Chat History API] PUT error:', error);
    return NextResponse.json(
      { success: false, error: error.message },
      { status: 500 }
    );
  }
}

export async function DELETE(request: NextRequest) {
  try {
    const { searchParams } = new URL(request.url);
    const chatId = searchParams.get('id');
    const folder = searchParams.get('folder');
    const userId = searchParams.get('userId') || 'aiascended-001';

    if (!chatId) {
      return NextResponse.json(
        { success: false, error: 'chatId is required' },
        { status: 400 }
      );
    }

    const filePath = await getChatFilePath(userId, chatId, folder);
    await fs.unlink(filePath);

    return NextResponse.json({ success: true });
  } catch (error: any) {
    console.error('[Chat History API] DELETE error:', error);
    return NextResponse.json(
      { success: false, error: error.message },
      { status: 500 }
    );
  }
}

/**
 * Health Check API Endpoint
 * Enterprise-grade health monitoring for production readiness
 */

import { NextRequest, NextResponse } from 'next/server';
import { getHealthStatus, addSecurityHeaders, generateRequestId } from '@/lib/productionHardening';

export async function GET(request: NextRequest) {
  const requestId = generateRequestId();

  try {
    const health = await getHealthStatus();

    const statusCode = health.status === 'healthy' ? 200 : health.status === 'degraded' ? 200 : 503;

    const response = NextResponse.json(health, { status: statusCode });
    response.headers.set('X-Request-Id', requestId);
    response.headers.set('Cache-Control', 'no-cache, no-store, must-revalidate');

    return addSecurityHeaders(response);

  } catch (error) {
    const response = NextResponse.json(
      {
        status: 'unhealthy',
        timestamp: new Date().toISOString(),
        error: 'Health check failed',
        requestId,
      },
      { status: 503 }
    );

    response.headers.set('X-Request-Id', requestId);
    return addSecurityHeaders(response);
  }
}

// Also support HEAD requests for basic uptime monitoring
export async function HEAD(request: NextRequest) {
  return new NextResponse(null, { status: 200 });
}

"use client";

import React, { useState, useRef, useEffect } from 'react';
import { Button } from '@/components/ui/button';
import { ScrollArea } from '@/components/ui/scroll-area';
import { Textarea } from '@/components/ui/textarea';
import { Send, Bot, User, Code2, FileCode, Bug, Sparkles, Copy, FileDown, Play, Check } from 'lucide-react';
import { aiAssistant, type IDEContext } from '@/lib/ide/aiAssistant';
import { useEditorStore } from '@/lib/ide/editorStore';
import { useFileSystem } from '@/lib/ide/useFileSystem';
import Prism from 'prismjs';
import 'prismjs/themes/prism-tomorrow.css';
import 'prismjs/components/prism-javascript';
import 'prismjs/components/prism-typescript';
import 'prismjs/components/prism-jsx';
import 'prismjs/components/prism-tsx';
import 'prismjs/components/prism-css';
import 'prismjs/components/prism-json';
import 'prismjs/components/prism-python';

interface Message {
  id: string;
  role: 'user' | 'assistant';
  content: string;
  timestamp: Date;
  codeBlocks?: Array<{
    language: string;
    code: string;
    filename?: string;
  }>;
  domains?: string[];
}

const quickActions = [
  { icon: Code2, label: 'Explain Code', action: 'explain' },
  { icon: FileCode, label: 'Generate Code', action: 'generate' },
  { icon: Bug, label: 'Fix Bug', action: 'fix' },
  { icon: Sparkles, label: 'Optimize', action: 'optimize' },
];

export function AIChatPanel() {
  const [messages, setMessages] = useState<Message[]>([
    {
      id: '1',
      role: 'assistant',
      content: 'Hello! I\'m your ZacAi coding assistant powered by 23 knowledge domains and 13 AI models. I can help you with:\n\n• Code explanation and documentation\n• Bug fixing and debugging\n• Code generation and refactoring\n• Best practices and optimization\n• Testing and security analysis\n\nSelect code in the editor and use the quick actions, or just ask me anything!',
      timestamp: new Date(),
    },
  ]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [isInitialized, setIsInitialized] = useState(false);
  const [copiedCode, setCopiedCode] = useState<string | null>(null);
  const scrollRef = useRef<HTMLDivElement>(null);
  const {
    tabs,
    activeTabId,
    getTab,
    updateTabContent,
  } = useEditorStore();
  const { fileTree, writeFile } = useFileSystem();

  // Initialize AI assistant
  useEffect(() => {
    const initAI = async () => {
      try {
        await aiAssistant.initialize();
        setIsInitialized(true);
      } catch (error) {
        console.error('Failed to initialize AI:', error);
      }
    };
    initAI();
  }, []);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  // Build IDE context
  const getIDEContext = (): IDEContext => {
    const activeFile = activeTabId ? getTab(activeTabId) : undefined;
    const projectFiles = fileTree.map((node) => node.path);

    return {
      currentFile: activeFile
        ? {
            path: activeFile.path,
            content: activeFile.content,
            language: activeFile.language,
          }
        : undefined,
      openFiles: tabs.map((file) => ({
        path: file.path,
        content: file.content,
        language: file.language,
      })),
      projectFiles,
    };
  };

  const handleSend = async () => {
    if (!input.trim() || isLoading || !isInitialized) return;

    const userMessage: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: input,
      timestamp: new Date(),
    };

    setMessages((prev) => [...prev, userMessage]);
    setInput('');
    setIsLoading(true);

    try {
      const context = getIDEContext();
      const response = await aiAssistant.sendMessage(input, context);

      const aiMessage: Message = {
        id: (Date.now() + 1).toString(),
        role: 'assistant',
        content: response.text,
        timestamp: new Date(),
        codeBlocks: response.codeBlocks,
        domains: response.domains,
      };

      setMessages((prev) => [...prev, aiMessage]);
    } catch (error) {
      const errorMessage: Message = {
        id: (Date.now() + 1).toString(),
        role: 'assistant',
        content: `Sorry, I encountered an error: ${error instanceof Error ? error.message : 'Unknown error'}. Please try again.`,
        timestamp: new Date(),
      };
      setMessages((prev) => [...prev, errorMessage]);
    } finally {
      setIsLoading(false);
    }
  };

  const handleQuickAction = async (action: string) => {
    const activeFile = activeTabId ? getTab(activeTabId) : undefined;

    if (!activeFile) {
      setInput(`${action} code for: `);
      return;
    }

    setIsLoading(true);

    try {
      let response;
      const code = activeFile.content;
      const language = activeFile.language;

      switch (action) {
        case 'explain':
          response = await aiAssistant.explainCode(code, language);
          break;
        case 'fix':
          response = await aiAssistant.fixCode(code, language);
          break;
        case 'optimize':
          response = await aiAssistant.optimizeCode(code, language);
          break;
        case 'generate':
          setInput('Generate code for: ');
          setIsLoading(false);
          return;
        default:
          setIsLoading(false);
          return;
      }

      const aiMessage: Message = {
        id: Date.now().toString(),
        role: 'assistant',
        content: response.text,
        timestamp: new Date(),
        codeBlocks: response.codeBlocks,
        domains: response.domains,
      };

      setMessages((prev) => [...prev, aiMessage]);
    } catch (error) {
      console.error('Quick action error:', error);
    } finally {
      setIsLoading(false);
    }
  };

  const handleCopyCode = (code: string, id: string) => {
    navigator.clipboard.writeText(code);
    setCopiedCode(id);
    setTimeout(() => setCopiedCode(null), 2000);
  };

  const handleInsertCode = async (code: string, filename?: string) => {
    if (filename) {
      // Create new file
      try {
        const path = `/${filename}`;
        await writeFile(path, code);
        // The file system hook will refresh the tree
      } catch (error) {
        console.error('Failed to create file:', error);
      }
    } else if (activeTabId) {
      // Insert into active file
      const activeFile = getTab(activeTabId);
      if (activeFile) {
        updateTabContent(activeFile.id, code);
      }
    }
  };

  return (
    <div className="h-full flex flex-col bg-background">
      {/* Header */}
      <div className="p-3 border-b">
        <div className="flex items-center gap-2">
          <Bot className="h-5 w-5 text-primary" />
          <span className="font-semibold">AI Assistant</span>
        </div>
      </div>

      {/* Quick Actions */}
      <div className="p-2 border-b">
        <div className="grid grid-cols-2 gap-1">
          {quickActions.map((action) => (
            <Button
              key={action.label}
              variant="ghost"
              size="sm"
              className="justify-start text-xs h-8"
              onClick={() => handleQuickAction(action.action)}
            >
              <action.icon className="h-3 w-3 mr-1" />
              {action.label}
            </Button>
          ))}
        </div>
      </div>

      {/* Messages */}
      <ScrollArea className="flex-1 p-3" ref={scrollRef}>
        <div className="space-y-4">
          {messages.map((message) => (
            <div key={message.id}>
              <div
                className={`flex gap-2 ${
                  message.role === 'user' ? 'justify-end' : 'justify-start'
                }`}
              >
                {message.role === 'assistant' && (
                  <div className="flex-shrink-0 w-8 h-8 rounded-full bg-primary/10 flex items-center justify-center">
                    <Bot className="h-4 w-4 text-primary" />
                  </div>
                )}

                <div
                  className={`max-w-[85%] rounded-lg p-3 ${
                    message.role === 'user'
                      ? 'bg-primary text-primary-foreground'
                      : 'bg-muted'
                  }`}
                >
                  <p className="text-sm whitespace-pre-wrap">{message.content}</p>

                  {message.domains && message.domains.length > 0 && (
                    <div className="flex flex-wrap gap-1 mt-2">
                      {message.domains.slice(0, 3).map((domain) => (
                        <span
                          key={domain}
                          className="text-xs px-2 py-0.5 rounded-full bg-primary/20 text-primary"
                        >
                          {domain.replace('_', ' ')}
                        </span>
                      ))}
                    </div>
                  )}

                  <span className="text-xs opacity-70 mt-1 block">
                    {message.timestamp.toLocaleTimeString()}
                  </span>
                </div>

                {message.role === 'user' && (
                  <div className="flex-shrink-0 w-8 h-8 rounded-full bg-primary flex items-center justify-center">
                    <User className="h-4 w-4 text-primary-foreground" />
                  </div>
                )}
              </div>

              {/* Code blocks with actions */}
              {message.codeBlocks && message.codeBlocks.length > 0 && (
                <div className="ml-10 mt-2 space-y-2">
                  {message.codeBlocks.map((block, idx) => {
                    const blockId = `${message.id}-${idx}`;
                    const highlightedCode = Prism.highlight(
                      block.code,
                      Prism.languages[block.language] || Prism.languages.plaintext,
                      block.language
                    );

                    return (
                      <div
                        key={idx}
                        className="rounded-lg overflow-hidden border bg-background"
                      >
                        <div className="flex items-center justify-between px-3 py-2 bg-muted/50 border-b">
                          <div className="flex items-center gap-2">
                            <span className="text-xs font-semibold text-muted-foreground">
                              {block.language}
                            </span>
                            {block.filename && (
                              <span className="text-xs text-muted-foreground">
                                {block.filename}
                              </span>
                            )}
                          </div>
                          <div className="flex items-center gap-1">
                            <Button
                              variant="ghost"
                              size="sm"
                              className="h-6 px-2 text-xs"
                              onClick={() => handleCopyCode(block.code, blockId)}
                            >
                              {copiedCode === blockId ? (
                                <>
                                  <Check className="h-3 w-3 mr-1" />
                                  Copied
                                </>
                              ) : (
                                <>
                                  <Copy className="h-3 w-3 mr-1" />
                                  Copy
                                </>
                              )}
                            </Button>
                            <Button
                              variant="ghost"
                              size="sm"
                              className="h-6 px-2 text-xs"
                              onClick={() => handleInsertCode(block.code, block.filename)}
                            >
                              <FileDown className="h-3 w-3 mr-1" />
                              {block.filename ? 'Create File' : 'Insert'}
                            </Button>
                          </div>
                        </div>
                        <div className="p-3 overflow-x-auto">
                          <pre className="text-xs">
                            <code
                              dangerouslySetInnerHTML={{ __html: highlightedCode }}
                            />
                          </pre>
                        </div>
                      </div>
                    );
                  })}
                </div>
              )}
            </div>
          ))}

          {isLoading && (
            <div className="flex gap-2">
              <div className="flex-shrink-0 w-8 h-8 rounded-full bg-primary/10 flex items-center justify-center">
                <Bot className="h-4 w-4 text-primary animate-pulse" />
              </div>
              <div className="bg-muted rounded-lg p-3">
                <div className="flex gap-1">
                  <div className="w-2 h-2 bg-primary/40 rounded-full animate-bounce" />
                  <div className="w-2 h-2 bg-primary/40 rounded-full animate-bounce delay-100" />
                  <div className="w-2 h-2 bg-primary/40 rounded-full animate-bounce delay-200" />
                </div>
              </div>
            </div>
          )}
        </div>
      </ScrollArea>

      {/* Input */}
      <div className="p-3 border-t">
        <div className="flex gap-2">
          <Textarea
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === 'Enter' && !e.shiftKey) {
                e.preventDefault();
                handleSend();
              }
            }}
            placeholder="Ask me anything about your code..."
            className="min-h-[60px] max-h-[120px] resize-none"
            disabled={isLoading || !isInitialized}
          />
          <Button
            onClick={handleSend}
            disabled={!input.trim() || isLoading || !isInitialized}
            size="icon"
            className="flex-shrink-0"
          >
            <Send className="h-4 w-4" />
          </Button>
        </div>
        <p className="text-xs text-muted-foreground mt-2">
          {isInitialized ? (
            <>
              ✅ Phase 5 Complete: AI-powered coding assistant active
            </>
          ) : (
            <>
              Initializing AI assistant...
            </>
          )}
        </p>
      </div>
    </div>
  );
}

