    setupHoverProviders(monacoInstance);
  };

  const registerCustomSnippets = (monacoInstance: typeof monaco) => {
    // Register common code snippets
    const languages = ['javascript', 'typescript', 'javascriptreact', 'typescriptreact'];

    languages.forEach((lang) => {
      monacoInstance.languages.registerCompletionItemProvider(lang, {
        provideCompletionItems: (model, position, _context, _token) => {
          const word = model.getWordUntilPosition(position);
          const range = new monacoInstance.Range(
            position.lineNumber,
            word.startColumn,
            position.lineNumber,
            word.endColumn
          );

          const baseSuggestions = [
            {
              label: 'log',
              kind: monacoInstance.languages.CompletionItemKind.Snippet,
              insertText: "console.log('${1}');",
              documentation: 'Console log',
            },
            {
              label: 'func',
              kind: monacoInstance.languages.CompletionItemKind.Snippet,
              insertText: 'function ${1:name}(${2:params}) {\n\t${3}\n}',
              documentation: 'Function declaration',
            },
            {
              label: 'arrow',
              kind: monacoInstance.languages.CompletionItemKind.Snippet,
              insertText: 'const ${1:name} = (${2:params}) => {\n\t${3}\n};',
              documentation: 'Arrow function',
            },
            {
              label: 'async',
              kind: monacoInstance.languages.CompletionItemKind.Snippet,
              insertText: 'async function ${1:name}(${2:params}) {\n\t${3}\n}',
              documentation: 'Async function',
            },
            {
              label: 'try',
              kind: monacoInstance.languages.CompletionItemKind.Snippet,
              insertText: 'try {\n\t${1}\n} catch (error) {\n\t${2:console.error(error);}\n}',
              documentation: 'Try-catch block',
            },
          ];

          const suggestions = baseSuggestions.map((suggestion) => ({
            ...suggestion,
            range,
            insertTextRules: monacoInstance.languages.CompletionItemInsertTextRule.InsertAsSnippet,
          }));

          return { suggestions };
        },
      });
    });
  };

  const setupHoverProviders = (monacoInstance: typeof monaco) => {
    // Add hover documentation for common functions
    const languages = ['javascript', 'typescript', 'javascriptreact', 'typescriptreact'];

    languages.forEach((lang) => {
      monacoInstance.languages.registerHoverProvider(lang, {
        provideHover: (model, position) => {
          const word = model.getWordAtPosition(position);
          if (!word) return null;

          // Custom hover documentation
          const docs: Record<string, string> = {
            'console': 'The console object provides access to the debugging console',
            'log': 'Outputs a message to the console',
            'async': 'The async keyword declares an asynchronous function',
            'await': 'The await operator waits for a Promise to resolve',
          };

          const documentation = docs[word.word];
          if (documentation) {
            return {
              range: new monacoInstance.Range(
                position.lineNumber,
                word.startColumn,
                position.lineNumber,
                word.endColumn
              ),
              contents: [{ value: `**${word.word}**\n\n${documentation}` }],
            };
          }

          return null;
        },
      });
    });
  };

  const handleSave = async () => {
    if (!activeFile) return;
    try {
      await writeFile(activeFile.path, activeFile.content);
      markTabDirty(activeFile.id, false);
    } catch (error) {
      console.error('Failed to save file:', error);
    }
  };

  const handleChange = (value: string | undefined) => {
    if (value !== undefined && activeFile) {
      updateTabContent(activeFile.id, value);
    }
  };

  const handleCloseTab = (fileId: string, e: React.MouseEvent) => {
    e.stopPropagation();
    closeTab(fileId);
  };

  // Update editor content when active file changes
  useEffect(() => {
    if (editorRef.current && activeFile) {
      const currentModel = editorRef.current.getModel();
      if (currentModel) {
        const currentValue = currentModel.getValue();
        if (currentValue !== activeFile.content) {
          editorRef.current.setValue(activeFile.content);
        }
      }

      // Update language
      if (monacoRef.current && currentModel) {
        monacoRef.current.editor.setModelLanguage(currentModel, activeFile.language);
      }
    }
  }, [activeFile?.id, activeFile?.content, activeFile?.language]);

  if (tabs.length === 0) {
    return (
      <div className="h-full w-full flex items-center justify-center bg-background">
        <div className="text-center space-y-4">
          <FileCode className="h-16 w-16 mx-auto text-muted-foreground/50" />
          <div>
            <h3 className="text-lg font-semibold">No files open</h3>
            <p className="text-sm text-muted-foreground mt-2">
              Open a file from the explorer or create a new one to start coding
            </p>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="h-full w-full flex flex-col bg-background">
      {/* Tabs */}
      <div className="flex items-center bg-muted/30 border-b overflow-x-auto">
        {tabs.map((file) => (
          <div
            key={file.id}
            className={cn(
              'flex items-center gap-2 px-4 py-2 border-r cursor-pointer transition-colors group',
              file.id === activeTabId
                ? 'bg-background text-foreground'
                : 'hover:bg-muted/50 text-muted-foreground'
            )}
            onClick={() => setActiveTab(file.id)}
          >
            <span className="text-sm font-medium truncate max-w-[150px]">
              {file.path.split('/').pop()}
            </span>
            {file.isDirty && (
              <div className="w-2 h-2 rounded-full bg-primary" />
            )}
            <button
              className="opacity-0 group-hover:opacity-100 transition-opacity hover:bg-muted rounded p-0.5"
              onClick={(e) => handleCloseTab(file.id, e)}
            >
              <X className="h-3 w-3" />
            </button>
          </div>
        ))}
      </div>

      {/* Editor */}
      <div className="flex-1 relative">
        <Editor
          height="100%"
          language={activeFile?.language || 'typescript'}
          value={activeFile?.content || ''}
          theme={theme}
          onMount={handleEditorDidMount}
          onChange={handleChange}
          options={{
            selectOnLineNumbers: true,
            roundedSelection: false,
            readOnly: false,
            cursorStyle: 'line',
            automaticLayout: true,
          }}
        />

        {/* Status bar */}
        <div className="absolute bottom-0 left-0 right-0 flex items-center justify-between px-3 py-1 bg-muted/50 border-t text-xs">
          <div className="flex items-center gap-4">
            <span className="text-muted-foreground">
              {activeFile?.language.toUpperCase()}
            </span>
            <span className="text-muted-foreground">
              {activeFile?.path}
            </span>
            {activeFile?.isDirty && (
              <span className="text-yellow-600 dark:text-yellow-500">
                • Modified
              </span>
            )}
          </div>
          <div className="flex items-center gap-2">
            <Button
              variant="ghost"
              size="sm"
              className="h-6 px-2 text-xs"
              onClick={() => setTheme(theme === 'vs-dark' ? 'light' : 'vs-dark')}
            >
              {theme === 'vs-dark' ? '☀️ Light' : '🌙 Dark'}
            </Button>
            <span className="text-green-600 dark:text-green-500">
              ✅ Phase 6 Complete
            </span>
          </div>
        </div>
      </div>
    </div>
  );
}

"use client";

import React, { useState } from 'react';
import {
  FolderIcon,
  FolderOpen,
  FileIcon,
  FileCode,
  FileJson,
  Image,
  ChevronRight,
  ChevronDown,
  Plus,
  Search,
  RefreshCw,
} from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import {
  ContextMenu,
  ContextMenuContent,
  ContextMenuItem,
  ContextMenuTrigger,
} from '@/components/ui/context-menu';

interface FileNode {
  name: string;
  path: string;
  type: 'file' | 'directory';
  children?: FileNode[];
  expanded?: boolean;
}

// Sample file tree structure
const sampleFileTree: FileNode[] = [
  {
    name: 'src',
    path: '/src',
    type: 'directory',
    expanded: true,
    children: [
      {
        name: 'components',
        path: '/src/components',
        type: 'directory',
        expanded: false,
        children: [
          { name: 'Button.tsx', path: '/src/components/Button.tsx', type: 'file' },
          { name: 'Card.tsx', path: '/src/components/Card.tsx', type: 'file' },
        ],
      },
      { name: 'app.tsx', path: '/src/app.tsx', type: 'file' },
      { name: 'index.tsx', path: '/src/index.tsx', type: 'file' },
    ],
  },
  {
    name: 'public',
    path: '/public',
    type: 'directory',
    expanded: false,
    children: [
      { name: 'logo.png', path: '/public/logo.png', type: 'file' },
    ],
  },
  { name: 'package.json', path: '/package.json', type: 'file' },
  { name: 'tsconfig.json', path: '/tsconfig.json', type: 'file' },
  { name: 'README.md', path: '/README.md', type: 'file' },
];

function getFileIcon(fileName: string) {
  const ext = fileName.split('.').pop()?.toLowerCase();

  switch (ext) {
    case 'tsx':
    case 'jsx':
    case 'ts':
    case 'js':
      return <FileCode className="w-4 h-4 text-blue-400" />;
    case 'json':
      return <FileJson className="w-4 h-4 text-yellow-400" />;
    case 'png':
    case 'jpg':
    case 'svg':
    case 'gif':
      return <Image className="w-4 h-4 text-purple-400" />;
    default:
      return <FileIcon className="w-4 h-4 text-gray-400" />;
  }
}

function FileTreeNode({
  node,
  level = 0,
  onToggle,
  onSelect,
  selectedPath,
}: {
  node: FileNode;
  level?: number;
  onToggle: (path: string) => void;
  onSelect: (node: FileNode) => void;
  selectedPath: string | null;
}) {
  const isSelected = selectedPath === node.path;

  const handleClick = () => {
    if (node.type === 'directory') {
      onToggle(node.path);
    } else {
      onSelect(node);
    }
  };

  return (
    <div>
      <ContextMenu>
        <ContextMenuTrigger>
          <div
            className={`flex items-center gap-1 py-1 px-2 cursor-pointer hover:bg-[#2a2d2e] ${
              isSelected ? 'bg-[#37373d]' : ''
            }`}
            style={{ paddingLeft: `${level * 12 + 8}px` }}
            onClick={handleClick}
          >
            {node.type === 'directory' && (
              <span className="flex-shrink-0">
                {node.expanded ? (
                  <ChevronDown className="w-4 h-4 text-gray-400" />
                ) : (
                  <ChevronRight className="w-4 h-4 text-gray-400" />
                )}
              </span>
            )}
            <span className="flex-shrink-0 ml-1">
              {node.type === 'directory' ? (
                node.expanded ? (
                  <FolderOpen className="w-4 h-4 text-yellow-500" />
                ) : (
                  <FolderIcon className="w-4 h-4 text-yellow-500" />
                )
              ) : (
                getFileIcon(node.name)
              )}
            </span>
            <span className="ml-1 text-sm text-gray-200 truncate">{node.name}</span>
          </div>
        </ContextMenuTrigger>
        <ContextMenuContent>
          <ContextMenuItem>New File</ContextMenuItem>
          <ContextMenuItem>New Folder</ContextMenuItem>
          <ContextMenuItem>Rename</ContextMenuItem>
          <ContextMenuItem>Delete</ContextMenuItem>
          <ContextMenuItem>Copy Path</ContextMenuItem>
        </ContextMenuContent>
      </ContextMenu>

      {node.type === 'directory' && node.expanded && node.children && (
        <div>
          {node.children.map((child) => (
            <FileTreeNode
              key={child.path}
              node={child}
              level={level + 1}
              onToggle={onToggle}
              onSelect={onSelect}
              selectedPath={selectedPath}
            />
          ))}
        </div>
      )}
    </div>
  );
}

export function FileExplorer() {
  const [fileTree, setFileTree] = useState<FileNode[]>(sampleFileTree);
  const [selectedPath, setSelectedPath] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState('');

  const toggleNode = (path: string) => {
    const toggleInTree = (nodes: FileNode[]): FileNode[] => {
      return nodes.map((node) => {
        if (node.path === path) {
          return { ...node, expanded: !node.expanded };
        }
        if (node.children) {
          return { ...node, children: toggleInTree(node.children) };
        }
        return node;
      });
    };
    setFileTree(toggleInTree(fileTree));
  };

  const handleSelect = (node: FileNode) => {
    setSelectedPath(node.path);
    // TODO: Open file in editor
    console.log('Selected file:', node.path);
  };

  return (
    <div className="h-full flex flex-col bg-[#252526]">
      {/* Header */}
      <div className="flex items-center justify-between p-2 border-b border-[#3e3e42]">
        <span className="text-xs font-semibold text-gray-300 uppercase">Explorer</span>
        <div className="flex items-center gap-1">
          <Button variant="ghost" size="icon" className="h-6 w-6">
            <Plus className="h-4 w-4" />
          </Button>
          <Button variant="ghost" size="icon" className="h-6 w-6">
            <RefreshCw className="h-4 w-4" />
          </Button>
        </div>
      </div>

      {/* Search */}
      <div className="p-2 border-b border-[#3e3e42]">
        <div className="relative">
          <Search className="absolute left-2 top-1/2 transform -translate-y-1/2 h-4 w-4 text-gray-500" />
          <Input
            type="text"
            placeholder="Search files..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="pl-8 h-8 bg-[#3c3c3c] border-[#3e3e42] text-sm text-gray-200"
          />
        </div>
      </div>

      {/* File Tree */}
      <div className="flex-1 overflow-y-auto">
        {fileTree.map((node) => (
          <FileTreeNode
            key={node.path}
            node={node}
            onToggle={toggleNode}
            onSelect={handleSelect}
            selectedPath={selectedPath}
          />
        ))}
      </div>

      {/* Footer */}
      <div className="p-2 border-t border-[#3e3e42] text-xs text-gray-500">
        <span>{fileTree.length} items</span>
      </div>
    </div>
  );
}

"use client";

import React, { useState, useEffect } from 'react';
import { Github, Search, GitBranch, Star, GitFork, Loader2, Download } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { ScrollArea } from '@/components/ui/scroll-area';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
} from '@/components/ui/dialog';
import { github } from '@/lib/ide/githubIntegration';
import { useToast } from '@/hooks/use-toast';

interface GitHubBrowserProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onCloneRepo?: (path: string) => void;
}

export function GitHubBrowser({ open, onOpenChange, onCloneRepo }: GitHubBrowserProps) {
  const [repos, setRepos] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [token, setToken] = useState('');
  const [authenticated, setAuthenticated] = useState(false);
  const { toast } = useToast();

  useEffect(() => {
    if (authenticated) {
      loadRepositories();
    }
  }, [authenticated]);

  const handleAuthenticate = () => {
    if (!token.trim()) {
      toast({
        title: 'Error',
        description: 'Please enter a GitHub token',
        variant: 'destructive',
      });
      return;
    }

    try {
      github.setToken(token);
      setAuthenticated(true);
      toast({
        title: 'Success',
        description: 'Authenticated with GitHub',
      });
    } catch (error) {
      toast({
        title: 'Error',
        description: 'Failed to authenticate',
        variant: 'destructive',
      });
    }
  };

  const loadRepositories = async () => {
    setLoading(true);
    try {
      const data = await github.listRepositories();
      setRepos(data);
    } catch (error) {
      toast({
        title: 'Error',
        description: 'Failed to load repositories',
        variant: 'destructive',
      });
    } finally {
      setLoading(false);
    }
  };

  const handleSearch = async () => {
    if (!searchQuery.trim()) {
      loadRepositories();
      return;
    }

    setLoading(true);
    try {
      const data = await github.searchRepositories(searchQuery);
      setRepos(data);
    } catch (error) {
      toast({
        title: 'Error',
        description: 'Search failed',
        variant: 'destructive',
      });
    } finally {
      setLoading(false);
    }
  };

  const handleClone = async (owner: string, repoName: string) => {
    setLoading(true);
    try {
      const path = await github.cloneRepositoryToVFS(owner, repoName);
      toast({
        title: 'Success',
        description: `Cloned ${owner}/${repoName} to ${path}`,
      });
      onCloneRepo?.(path);
      onOpenChange(false);
    } catch (error) {
      toast({
        title: 'Error',
        description: `Failed to clone ${owner}/${repoName}`,
        variant: 'destructive',
      });
    } finally {
      setLoading(false);
    }
  };

  if (!authenticated) {
    return (
      <Dialog open={open} onOpenChange={onOpenChange}>
        <DialogContent className="max-w-md bg-[#252526] border-[#3e3e42]">
          <DialogHeader>
            <DialogTitle className="text-gray-200 flex items-center gap-2">
              <Github className="w-5 h-5" />
              GitHub Authentication
            </DialogTitle>
            <DialogDescription className="text-gray-400">
              Enter your GitHub Personal Access Token to browse and clone repositories.
            </DialogDescription>
          </DialogHeader>

          <div className="space-y-4">
            <div>
              <Input
                type="password"
                placeholder="ghp_xxxxxxxxxxxx"
                value={token}
                onChange={(e) => setToken(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && handleAuthenticate()}
                className="bg-[#3c3c3c] border-[#3e3e42] text-gray-200"
              />
              <p className="text-xs text-gray-500 mt-2">
                Create a token at{' '}
                <a
                  href="https://github.com/settings/tokens"
                  target="_blank"
                  rel="noopener noreferrer"
                  className="text-blue-400 hover:underline"
                >
                  github.com/settings/tokens
                </a>
              </p>
            </div>

            <Button onClick={handleAuthenticate} className="w-full">
              <Github className="w-4 h-4 mr-2" />
              Authenticate
            </Button>
          </div>
        </DialogContent>
      </Dialog>
    );
  }

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-4xl h-[600px] bg-[#252526] border-[#3e3e42]">
        <DialogHeader>
          <DialogTitle className="text-gray-200 flex items-center gap-2">
            <Github className="w-5 h-5" />
            Browse GitHub Repositories
          </DialogTitle>
        </DialogHeader>

        <div className="flex-1 flex flex-col gap-4">
          <div className="flex gap-2">
            <div className="flex-1 relative">
              <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 h-4 w-4 text-gray-500" />
              <Input
                type="text"
                placeholder="Search repositories..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && handleSearch()}
                className="pl-10 bg-[#3c3c3c] border-[#3e3e42] text-gray-200"
              />
            </div>
            <Button onClick={handleSearch} disabled={loading}>
              {loading ? <Loader2 className="w-4 h-4 animate-spin" /> : <Search className="w-4 h-4" />}
            </Button>
          </div>

          <ScrollArea className="flex-1 rounded-md border border-[#3e3e42]">
            {loading ? (
              <div className="flex items-center justify-center h-full">
                <Loader2 className="w-8 h-8 animate-spin text-gray-500" />
              </div>
            ) : repos.length > 0 ? (
              <div className="p-2 space-y-2">
                {repos.map((repo) => (
                  <div
                    key={repo.id}
                    className="p-4 rounded bg-[#2a2d2e] hover:bg-[#37373d] border border-[#3e3e42]"
                  >
                    <div className="flex items-start justify-between">
                      <div className="flex-1 min-w-0">
                        <h3 className="text-sm font-semibold text-gray-200 truncate">
                          {repo.fullName}
                        </h3>
                        {repo.description && (
                          <p className="text-xs text-gray-400 mt-1 line-clamp-2">
                            {repo.description}
                          </p>
                        )}
                        <div className="flex items-center gap-4 mt-2 text-xs text-gray-500">
                          {repo.language && (
                            <span className="flex items-center gap-1">
                              <span className="w-2 h-2 rounded-full bg-blue-400"></span>
                              {repo.language}
                            </span>
                          )}
                          <span className="flex items-center gap-1">
                            <Star className="w-3 h-3" />
                            {repo.stars}
                          </span>
                          <span className="flex items-center gap-1">
                            <GitFork className="w-3 h-3" />
                            {repo.forks}
                          </span>
                        </div>
                      </div>
                      <Button
                        size="sm"
                        variant="outline"
                        onClick={() => handleClone(repo.owner, repo.name)}
                        disabled={loading}
                        className="ml-4"
                      >
                        <Download className="w-4 h-4 mr-1" />
                        Clone
                      </Button>
                    </div>
                  </div>
                ))}
              </div>
            ) : (
              <div className="flex items-center justify-center h-full text-gray-500">
                No repositories found
              </div>
            )}
          </ScrollArea>
        </div>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import React, { useState, useEffect, useRef } from 'react';
import { Button } from '@/components/ui/button';
import { RefreshCw, ExternalLink, Smartphone, Tablet, Monitor, AlertCircle } from 'lucide-react';
import { codeExecutor } from '@/lib/ide/codeExecutor';
import { useEditorStore } from '@/lib/ide/editorStore';
import { useFileSystem } from '@/lib/ide/useFileSystem';
import { ScrollArea } from '@/components/ui/scroll-area';

type DeviceSize = 'mobile' | 'tablet' | 'desktop';

interface ConsoleMessage {
  type: 'log' | 'warn' | 'error';
  message: string;
  timestamp: number;
}

export function PreviewPanel() {
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [deviceSize, setDeviceSize] = useState<DeviceSize>('desktop');
  const [previewContent, setPreviewContent] = useState('');
  const [consoleMessages, setConsoleMessages] = useState<ConsoleMessage[]>([]);
  const [showConsole, setShowConsole] = useState(false);
  const iframeRef = useRef<HTMLIFrameElement>(null);
  const { tabs, activeTabId, getTab } = useEditorStore();
  const { readFile } = useFileSystem();
  const getActiveFile = () => (activeTabId ? getTab(activeTabId) : undefined);

  // Auto-refresh when active file changes
  useEffect(() => {
    handleRefresh();
  }, [activeTabId, tabs]);

  // Listen for console messages from iframe
  useEffect(() => {
    const handleMessage = (event: MessageEvent) => {
      if (event.data.type === 'console') {
        setConsoleMessages((prev) => [
          ...prev,
          {
            type: event.data.level,
            message: event.data.args.join(' '),
            timestamp: Date.now(),
          },
        ]);
        setShowConsole(true);
      } else if (event.data.type === 'error') {
        setConsoleMessages((prev) => [
          ...prev,
          {
            type: 'error',
            message: `${event.data.message} (Line: ${event.data.line}, Col: ${event.data.col})`,
            timestamp: Date.now(),
          },
        ]);
        setShowConsole(true);
      }
    };

    window.addEventListener('message', handleMessage);
    return () => window.removeEventListener('message', handleMessage);
  }, []);

  const handleRefresh = async () => {
    setIsRefreshing(true);
    setConsoleMessages([]);

    try {
      // Get active file
      const activeFile = getActiveFile();

      if (!activeFile) {
        // Show default preview
        setPreviewContent(getDefaultPreview());
        return;
      }

      const filePath = activeFile.path;
      const extension = filePath.split('.').pop()?.toLowerCase();

      if (extension === 'html') {
        // HTML file - load as is with linked resources
        await generateHTMLPreview(filePath, activeFile.content);
      } else if (extension === 'js' || extension === 'ts') {
        // JavaScript/TypeScript - execute and show results
        await generateJSPreview(activeFile.content);
      } else if (extension === 'css') {
        // CSS - create a demo HTML with the styles
        await generateCSSPreview(activeFile.content);
      } else if (['jsx', 'tsx'].includes(extension || '')) {
        // React components - show message about future support
        setPreviewContent(getReactPreview());
      } else {
        // Unsupported - show default
        setPreviewContent(getDefaultPreview());
      }
    } catch (error) {
      console.error('Preview error:', error);
      setPreviewContent(getErrorPreview(String(error)));
    } finally {
      setIsRefreshing(false);
    }
  };

  const readFileContent = async (path: string) => {
    const file = await readFile(path);
    if (!file) {
      throw new Error(`File not found: ${path}`);
    }
    return file.content;
  };

  const generateHTMLPreview = async (filePath: string, htmlContent: string) => {
    try {
      // Try to load referenced CSS and JS files
      const dirPath = filePath.split('/').slice(0, -1).join('/');

      // Simple parsing for linked resources
      let processedHTML = htmlContent;

      // Find and inline CSS
      const cssMatches = htmlContent.match(/<link[^>]*href=["']([^"']+\.css)["'][^>]*>/g);
      if (cssMatches) {
        for (const match of cssMatches) {
          const hrefMatch = match.match(/href=["']([^"']+)["']/);
          if (hrefMatch) {
            const cssPath = `${dirPath ? dirPath : ''}/${hrefMatch[1]}`.replace(/\/+/g, '/');
            try {
              const cssContent = await readFileContent(cssPath);
              processedHTML = processedHTML.replace(
                match,
                `<style>${cssContent}</style>`
              );
            } catch {
              // CSS file not found, leave as is
            }
          }
        }
      }

      setPreviewContent(processedHTML);
    } catch (error) {
      setPreviewContent(getErrorPreview(`Failed to load HTML: ${error}`));
    }
  };

  const generateJSPreview = async (jsCode: string) => {
    const html = `
      <div style="font-family: 'Courier New', monospace; padding: 20px;">
        <h2>JavaScript Output</h2>
        <div id="output" style="background: #f5f5f5; padding: 15px; border-radius: 5px; margin-top: 10px;">
          <p style="color: #666;">Executing...</p>
        </div>
      </div>
    `;

    const js = `
      try {
        const output = document.getElementById('output');
        output.innerHTML = '';

        // Capture console.log output
        const originalLog = console.log;
        const logs = [];
        console.log = function(...args) {
          logs.push(args.map(arg => {
            if (typeof arg === 'object') {
              try { return JSON.stringify(arg, null, 2); }
              catch { return String(arg); }
            }
            return String(arg);
          }).join(' '));
          originalLog.apply(console, args);
        };

        // Execute user code
        ${jsCode}

        // Display logs
        if (logs.length > 0) {
          output.innerHTML = '<pre style="margin: 0;">' + logs.join('\\n') + '</pre>';
        } else {
          output.innerHTML = '<p style="color: #666; margin: 0;">No output</p>';
        }

        console.log = originalLog;
      } catch (error) {
        document.getElementById('output').innerHTML = 
          '<p style="color: #d32f2f; margin: 0;">Error: ' + error.message + '</p>';
      }
    `;

    const preview = await codeExecutor.executePreview(html, '', js);
    setPreviewContent(preview);
  };

  const generateCSSPreview = async (cssCode: string) => {
    const html = `
      <div class="demo-container">
        <h1>CSS Preview</h1>
        <p class="text-content">This is a sample paragraph to demonstrate the CSS styles.</p>
