        padding: 20px;
        margin: 0;
      }
      ${cssCode}
    `;

    const preview = await codeExecutor.executePreview(html, css, '');
    setPreviewContent(preview);
  };

  const getDefaultPreview = () => {
    return `
      <!DOCTYPE html>
      <html lang="en">
      <head>
