"use client";

import React, { useState, useEffect, useCallback } from 'react';
import { Search, FileIcon, FileCode } from 'lucide-react';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import { Input } from '@/components/ui/input';
import { ScrollArea } from '@/components/ui/scroll-area';
import { useFileSystem } from '@/lib/ide/useFileSystem';
import { useEditorStore } from '@/lib/ide/editorStore';

interface QuickOpenProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
}

export function QuickOpen({ open, onOpenChange }: QuickOpenProps) {
  const [query, setQuery] = useState('');
  const [selectedIndex, setSelectedIndex] = useState(0);
  const [results, setResults] = useState<any[]>([]);
  const { searchFiles } = useFileSystem();
  const { openFile } = useEditorStore();

  const performSearch = useCallback(async (searchQuery: string) => {
    if (!searchQuery.trim()) {
      setResults([]);
      return;
    }

    try {
      const files = await searchFiles(searchQuery);
      setResults(files.slice(0, 20)); // Limit to 20 results
      setSelectedIndex(0);
    } catch (error) {
      console.error('Search error:', error);
      setResults([]);
    }
  }, [searchFiles]);

  useEffect(() => {
    const debounce = setTimeout(() => {
      performSearch(query);
    }, 200);

    return () => clearTimeout(debounce);
  }, [query, performSearch]);

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'ArrowDown') {
      e.preventDefault();
      setSelectedIndex((prev) => Math.min(prev + 1, results.length - 1));
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      setSelectedIndex((prev) => Math.max(prev - 1, 0));
    } else if (e.key === 'Enter') {
      e.preventDefault();
      if (results[selectedIndex]) {
        handleSelectFile(results[selectedIndex]);
      }
    }
  };

  const handleSelectFile = async (file: any) => {
    try {
      const fileName = file.path.split('/').pop() || file.path;
      openFile(file.path, fileName, file.content, file.language);
      onOpenChange(false);
      setQuery('');
    } catch (error) {
      console.error('Failed to open file:', error);
    }
  };

  const getFileIcon = (language: string) => {
    if (['typescript', 'javascript'].includes(language)) {
      return <FileCode className="w-4 h-4 text-blue-400" />;
    }
    return <FileIcon className="w-4 h-4 text-gray-400" />;
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-2xl bg-[#252526] border-[#3e3e42]">
        <DialogHeader>
          <DialogTitle className="text-gray-200">Quick Open File</DialogTitle>
        </DialogHeader>

        <div className="space-y-4">
          <div className="relative">
            <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 h-4 w-4 text-gray-500" />
            <Input
              type="text"
              placeholder="Type to search files..."
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              onKeyDown={handleKeyDown}
              className="pl-10 bg-[#3c3c3c] border-[#3e3e42] text-gray-200"
              autoFocus
            />
          </div>

          <ScrollArea className="h-[400px] rounded-md border border-[#3e3e42]">
            {results.length > 0 ? (
              <div className="p-2">
                {results.map((file, index) => (
                  <div
                    key={file.path}
                    className={`flex items-center gap-3 p-3 rounded cursor-pointer ${
                      index === selectedIndex
                        ? 'bg-[#37373d]'
                        : 'hover:bg-[#2a2d2e]'
                    }`}
                    onClick={() => handleSelectFile(file)}
                    onMouseEnter={() => setSelectedIndex(index)}
                  >
                    {getFileIcon(file.language)}
                    <div className="flex-1 min-w-0">
                      <div className="text-sm text-gray-200 truncate">
                        {file.path.split('/').pop()}
                      </div>
                      <div className="text-xs text-gray-500 truncate">
                        {file.path}
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            ) : query.trim() ? (
              <div className="flex items-center justify-center h-full text-gray-500">
                No files found
              </div>
            ) : (
              <div className="flex items-center justify-center h-full text-gray-500">
                Start typing to search...
              </div>
            )}
          </ScrollArea>

          <div className="flex items-center justify-between text-xs text-gray-500">
            <span>Use ↑↓ to navigate, Enter to open, Esc to close</span>
            {results.length > 0 && (
              <span>{results.length} {results.length === 1 ? 'result' : 'results'}</span>
            )}
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import React, { useEffect, useMemo, useRef, useState } from 'react';
import { Terminal as XTerm } from 'xterm';
import { FitAddon } from 'xterm-addon-fit';
import { WebLinksAddon } from 'xterm-addon-web-links';
import 'xterm/css/xterm.css';
import { Button } from '@/components/ui/button';
import { X, Plus } from 'lucide-react';
import { CommandProcessor } from '@/lib/ide/commandProcessor';
import type { CommandFileSystem, CommandFileSystemEntry } from '@/lib/ide/commandProcessor';
import { vfs } from '@/lib/ide/virtualFileSystem';
import type { IDEFile } from '@/lib/ide/virtualFileSystem';

interface TerminalSession {
  id: string;
  title: string;
  terminal: XTerm;
  commandProcessor: CommandProcessor;
  currentLine: string;
  cursorPosition: number;
}

export function TerminalPanel() {
  const terminalRef = useRef<HTMLDivElement>(null);
  const [sessions, setSessions] = useState<TerminalSession[]>([]);
  const [activeSessionId, setActiveSessionId] = useState<string | null>(null);
  const sessionsRef = useRef<TerminalSession[]>([]);
  const fitAddonRef = useRef<FitAddon | null>(null);

  const commandFs = useMemo(() => createCommandFileSystem(), []);

  const createSession = (title: string, index: number) => {
    if (!terminalRef.current) return null;

    const terminal = new XTerm({
      cursorBlink: true,
      fontSize: 14,
      fontFamily: 'Menlo, Monaco, "Courier New", monospace',
      theme: {
        background: '#1e1e1e',
        foreground: '#d4d4d4',
        cursor: '#ffffff',
        selectionBackground: '#264f78',
        black: '#000000',
        red: '#cd3131',
        green: '#0dbc79',
        yellow: '#e5e510',
        blue: '#2472c8',
        magenta: '#bc3fbc',
        cyan: '#11a8cd',
        white: '#e5e5e5',
        brightBlack: '#666666',
        brightRed: '#f14c4c',
        brightGreen: '#23d18b',
        brightYellow: '#f5f543',
        brightBlue: '#3b8eea',
        brightMagenta: '#d670d6',
        brightCyan: '#29b8db',
        brightWhite: '#e5e5e5',
      },
      scrollback: 10000,
      convertEol: true,
    });

    const fitAddon = new FitAddon();
    const webLinksAddon = new WebLinksAddon();

    terminal.loadAddon(fitAddon);
    terminal.loadAddon(webLinksAddon);
    fitAddonRef.current = fitAddon;

    terminal.open(terminalRef.current);
    fitAddon.fit();

    const commandProcessor = new CommandProcessor(commandFs);
    const sessionId = `session-${Date.now()}-${index}`;

    // Welcome message
    if (index === 0) {
      terminal.writeln('\x1b[1;32m╔═══════════════════════════════════════════════╗\x1b[0m');
      terminal.writeln('\x1b[1;32m║     Welcome to ZacAi IDE Terminal            ║\x1b[0m');
      terminal.writeln('\x1b[1;32m╚═══════════════════════════════════════════════╝\x1b[0m');
      terminal.writeln('');
      terminal.writeln('\x1b[1;36mType "help" for available commands\x1b[0m');
      terminal.writeln('');
    }

    const session: TerminalSession = {
      id: sessionId,
      title,
      terminal,
      commandProcessor,
      currentLine: '',
      cursorPosition: 0,
    };

    // Show prompt
    terminal.write(commandProcessor.getPrompt());

    // Handle input
    terminal.onData(async (data: string) => {
      const charCode = data.charCodeAt(0);

      if (data === '\r') {
        // Enter key - execute command
        terminal.write('\r\n');

        if (session.currentLine.trim()) {
          const result = await commandProcessor.executeCommand(session.currentLine);

          // Handle special clear command
          if (result.output === '\x1bc') {
            terminal.clear();
          } else if (result.output) {
            terminal.write(result.output);
          }
        }

        session.currentLine = '';
        session.cursorPosition = 0;
        terminal.write(commandProcessor.getPrompt());
      } else if (data === '\u007F' || charCode === 8) {
        // Backspace
        if (session.cursorPosition > 0) {
          session.currentLine = 
            session.currentLine.slice(0, session.cursorPosition - 1) +
            session.currentLine.slice(session.cursorPosition);
          session.cursorPosition--;
          terminal.write('\b \b');
        }
      } else if (data === '\x1b[A') {
        // Up arrow - previous command
        const prevCommand = commandProcessor.getPreviousCommand();
        if (prevCommand) {
          // Clear current line
          terminal.write('\r' + commandProcessor.getPrompt());
          terminal.write(' '.repeat(session.currentLine.length));
          terminal.write('\r' + commandProcessor.getPrompt());

          // Write previous command
          terminal.write(prevCommand);
          session.currentLine = prevCommand;
          session.cursorPosition = prevCommand.length;
        }
      } else if (data === '\x1b[B') {
        // Down arrow - next command
        const nextCommand = commandProcessor.getNextCommand();
        if (nextCommand) {
          // Clear current line
          terminal.write('\r' + commandProcessor.getPrompt());
          terminal.write(' '.repeat(session.currentLine.length));
          terminal.write('\r' + commandProcessor.getPrompt());

          // Write next command
          terminal.write(nextCommand);
          session.currentLine = nextCommand;
          session.cursorPosition = nextCommand.length;
        }
      } else if (data === '\x1b[C') {
        // Right arrow
        if (session.cursorPosition < session.currentLine.length) {
          session.cursorPosition++;
          terminal.write(data);
        }
      } else if (data === '\x1b[D') {
        // Left arrow
        if (session.cursorPosition > 0) {
          session.cursorPosition--;
          terminal.write(data);
        }
      } else if (charCode >= 32 && charCode < 127) {
        // Printable character
        session.currentLine = 
          session.currentLine.slice(0, session.cursorPosition) +
          data +
          session.currentLine.slice(session.cursorPosition);
        session.cursorPosition++;
        terminal.write(data);
      }
    });

    return session;
  };

  useEffect(() => {
    sessionsRef.current = sessions;
  }, [sessions]);

  useEffect(() => {
    if (!terminalRef.current) return;

    const session = createSession('Terminal 1', 0);
    if (session) {
      setSessions([session]);
      setActiveSessionId(session.id);
    }

    // Handle resize
    const resizeObserver = new ResizeObserver(() => {
      if (fitAddonRef.current) {
        fitAddonRef.current.fit();
      }
    });

    if (terminalRef.current) {
      resizeObserver.observe(terminalRef.current);
    }

    return () => {
      resizeObserver.disconnect();
      sessionsRef.current.forEach((s) => s.terminal.dispose());
    };
  }, [commandFs]);

  const addSession = () => {
    const newSession = createSession(`Terminal ${sessions.length + 1}`, sessions.length);
    if (newSession) {
      setSessions([...sessions, newSession]);
      setActiveSessionId(newSession.id);
    }
  };

  const closeSession = (sessionId: string) => {
    const session = sessions.find((s) => s.id === sessionId);
    if (!session) return;

    session.terminal.dispose();
    const newSessions = sessions.filter((s) => s.id !== sessionId);
    setSessions(newSessions);

    if (newSessions.length === 0) {
      setActiveSessionId(null);
      return;
    }

    if (activeSessionId === sessionId) {
      setActiveSessionId(newSessions[0].id);
    }
  };

  return (
    <div className="h-full flex flex-col bg-[#1e1e1e]">
      {/* Terminal Tabs */}
      <div className="flex items-center gap-1 px-2 py-1 bg-[#252526] border-b border-[#3e3e42]">
        {sessions.map((session) => (
          <div
            key={session.id}
            className={`flex items-center gap-2 px-3 py-1 text-sm rounded-sm cursor-pointer transition-colors ${
              session.id === activeSessionId
                ? 'bg-[#1e1e1e] text-white'
                : 'text-gray-400 hover:bg-[#2a2d2e]'
            }`}
            onClick={() => setActiveSessionId(session.id)}
          >
            <span>{session.title}</span>
            <button
              className="hover:text-white transition-colors"
              onClick={(e) => {
                e.stopPropagation();
                closeSession(session.id);
              }}
            >
              <X className="h-3 w-3" />
            </button>
          </div>
        ))}
        <Button
          variant="ghost"
          size="sm"
          className="h-6 w-6 p-0 text-gray-400 hover:text-white"
          onClick={addSession}
        >
          <Plus className="h-4 w-4" />
        </Button>
      </div>

      {/* Terminal Container */}
      <div ref={terminalRef} className="flex-1 p-2 overflow-hidden" />

      <div className="px-2 py-1 border-t border-[#3e3e42] bg-[#252526]">
        <p className="text-xs text-gray-500">
          Phase 4: WebAssembly shell integration
        </p>
      </div>
    </div>
  );
}

const toEntry = (file: IDEFile): CommandFileSystemEntry => ({
  name: file.path === '/' ? '/' : file.path.split('/').pop() || file.path,
  path: file.path,
  type: file.type,
  metadata: {
    size: file.size,
    modified: file.updatedAt,
  },
});

const createCommandFileSystem = (): CommandFileSystem => ({
  async read(path: string) {
    const file = await vfs.readFile(path);
    if (!file) {
      throw new Error(`File not found: ${path}`);
    }
    if (file.type === 'directory') {
      throw new Error(`${path} is a directory`);
    }
    return file.content;
  },
  async write(path: string, content: string) {
    await vfs.writeFile(path, content);
  },
  async mkdir(path: string) {
    await vfs.createDirectory(path);
  },
  async delete(path: string) {
    await vfs.deleteFile(path);
  },
  async list(path: string) {
    const targetPath = path || '/';
    const node = await vfs.readFile(targetPath);
    if (!node) {
      throw new Error(`Path not found: ${path}`);
    }
    if (node.type === 'file') {
      return [toEntry(node)];
    }
    const children = await vfs.listDirectory(targetPath);
    return children.map(toEntry);
  },
  async exists(path: string) {
    const file = await vfs.readFile(path);
    return Boolean(file);
  },
  async search(query: string) {
    const results = await vfs.searchFiles(query);
    return results.map(toEntry);
  },
});

