      const data = await res.json();

      const assistantMessage: Message = {
        id: `assistant-${Date.now()}`,
        role: 'assistant',
        content: data.response || data.text || 'No response',
        contentBlocks: data.contentBlocks,
        thinkingSteps: data.thinkingSteps,
