interface ModelSettings {
  enabled: boolean
  type: string
  parameters: Record<string, any>
  performance: {
    maxLatency: number
    cacheEnabled: boolean
  }
  updatedAt: string
}

interface ModelSettingsPageProps {
  modelName: string
  modelTitle: string
  modelDescription: string
  defaultParameters: Record<string, any>
}

export function ModelSettingsPage({
  modelName,
  modelTitle,
  modelDescription,
  defaultParameters
}: ModelSettingsPageProps) {
  const [loading, setLoading] = useState(true)
  const [saving, setSaving] = useState(false)
  const [showSuccess, setShowSuccess] = useState(false)
  const [error, setError] = useState<string | null>(null)

  const [settings, setSettings] = useState<ModelSettings>({
    enabled: true,
    type: modelName,
    parameters: defaultParameters,
    performance: {
      maxLatency: 5000,
      cacheEnabled: true
    },
    updatedAt: new Date().toISOString()
  })

  useEffect(() => {
    loadSettings()
  }, [modelName])

  const loadSettings = async () => {
    try {
      setLoading(true)
      setError(null)
      const response = await fetch(`/api/admin/settings/models?name=${modelName}`)
      const result = await response.json()

      if (result.success) {
        setSettings(result.data)
      } else {
        setError(result.error || 'Failed to load settings')
      }
    } catch (err) {
      setError('Network error loading settings')
      console.error('[Model Settings] Load error:', err)
    } finally {
      setLoading(false)
    }
  }

  const saveSettings = async () => {
    try {
      setSaving(true)
      setError(null)
      setShowSuccess(false)

      const response = await fetch('/api/admin/settings/models', {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          modelName,
          settings: {
            ...settings,
            updatedAt: new Date().toISOString()
          }
        })
      })

      const result = await response.json()

      if (result.success) {
        setSettings(result.data)
        setShowSuccess(true)
        setTimeout(() => setShowSuccess(false), 3000)
      } else {
        setError(result.error || 'Failed to save settings')
      }
    } catch (err) {
      setError('Network error saving settings')
      console.error('[Model Settings] Save error:', err)
    } finally {
      setSaving(false)
    }
  }

  const resetToDefaults = () => {
    setSettings({
      enabled: true,
      type: modelName,
      parameters: defaultParameters,
      performance: {
        maxLatency: 5000,
        cacheEnabled: true
      },
      updatedAt: new Date().toISOString()
    })
  }

  const updateParameter = (key: string, value: any) => {
    setSettings({
      ...settings,
      parameters: {
        ...settings.parameters,
        [key]: value
      }
    })
  }

  if (loading) {
    return (
      <div className="flex items-center justify-center h-96">
        <div className="text-center space-y-4">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary mx-auto"></div>
          <p className="text-muted-foreground">Loading model settings...</p>
        </div>
      </div>
