          </div>
        </Card>
      )}

      <Tabs defaultValue="settings" className="space-y-4">
        <TabsList>
          <TabsTrigger value="settings">Settings</TabsTrigger>
          <TabsTrigger value="parameters">Parameters</TabsTrigger>
          <TabsTrigger value="performance">Performance</TabsTrigger>
        </TabsList>

        <TabsContent value="settings" className="space-y-4">
          <Card className="p-6 space-y-6">
            <div className="flex items-center justify-between">
              <div className="space-y-0.5">
                <Label htmlFor="enabled">Model Status</Label>
                <p className="text-sm text-muted-foreground">
                  Enable or disable this model
                </p>
              </div>
              <Switch 
                id="enabled"
                checked={settings.enabled}
                onCheckedChange={(checked) => setSettings({ ...settings, enabled: checked })}
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="type">Model Type</Label>
              <Input 
                id="type" 
                value={settings.type}
                onChange={(e) => setSettings({ ...settings, type: e.target.value })}
              />
            </div>

            <div className="p-4 bg-muted rounded-lg">
              <div className="flex items-center gap-2 mb-2">
                <Activity className="h-5 w-5" />
                <h3 className="font-semibold">Model Information</h3>
              </div>
              <div className="space-y-1 text-sm">
                <p><span className="font-medium">Model ID:</span> {modelName}</p>
                <p><span className="font-medium">Status:</span> {settings.enabled ? '✅ Active' : '❌ Disabled'}</p>
                <p><span className="font-medium">Parameters:</span> {Object.keys(settings.parameters).length} configured</p>
              </div>
            </div>
          </Card>
        </TabsContent>

        <TabsContent value="parameters" className="space-y-4">
          <Card className="p-6">
            <h2 className="text-xl font-semibold mb-4">Model Parameters</h2>
            <div className="space-y-4">
              {Object.entries(settings.parameters).map(([key, value]) => (
                <div key={key} className="space-y-2">
                  <Label htmlFor={key} className="capitalize">
                    {key.replace(/([A-Z])/g, ' $1').trim()}
                  </Label>
                  {typeof value === 'boolean' ? (
                    <Switch
                      id={key}
                      checked={value}
                      onCheckedChange={(checked) => updateParameter(key, checked)}
                    />
                  ) : typeof value === 'number' ? (
                    <Input
                      id={key}
                      type="number"
                      value={value}
                      onChange={(e) => updateParameter(key, parseFloat(e.target.value) || 0)}
                    />
                  ) : Array.isArray(value) ? (
                    <Textarea
                      id={key}
                      value={JSON.stringify(value, null, 2)}
                      onChange={(e) => {
                        try {
                          updateParameter(key, JSON.parse(e.target.value))
                        } catch {}
                      }}
                      className="font-mono text-sm"
                      rows={3}
                    />
                  ) : (
                    <Input
                      id={key}
                      value={String(value)}
                      onChange={(e) => updateParameter(key, e.target.value)}
                    />
                  )}
                </div>
              ))}
            </div>
          </Card>
        </TabsContent>

        <TabsContent value="performance" className="space-y-4">
          <Card className="p-6 space-y-6">
            <h2 className="text-xl font-semibold">Performance Settings</h2>

            <div className="space-y-2">
              <Label htmlFor="maxLatency">Max Latency (ms)</Label>
              <Input 
                id="maxLatency" 
                type="number" 
                value={settings.performance.maxLatency}
                onChange={(e) => setSettings({
                  ...settings,
                  performance: {
                    ...settings.performance,
                    maxLatency: parseInt(e.target.value) || 5000
                  }
                })}
              />
              <p className="text-sm text-muted-foreground">
                Maximum allowed response time in milliseconds
              </p>
            </div>

            <div className="flex items-center justify-between">
              <div className="space-y-0.5">
                <Label htmlFor="cacheEnabled">Enable Caching</Label>
                <p className="text-sm text-muted-foreground">
                  Cache responses for improved performance
                </p>
              </div>
              <Switch 
                id="cacheEnabled"
                checked={settings.performance.cacheEnabled}
                onCheckedChange={(checked) => setSettings({
                  ...settings,
                  performance: {
                    ...settings.performance,
                    cacheEnabled: checked
                  }
                })}
              />
            </div>
          </Card>
        </TabsContent>
      </Tabs>

      <div className="flex gap-3">
        <Button 
          onClick={saveSettings} 
          disabled={saving}
          className="flex items-center gap-2"
        >
          {saving ? (
            <>
              <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-white"></div>
              Saving...
            </>
          ) : (
            <>
              <Save className="h-4 w-4" />
              Save Settings
            </>
          )}
        </Button>

        <Button 
          variant="outline" 
          onClick={resetToDefaults}
          className="flex items-center gap-2"
        >
          <RotateCcw className="h-4 w-4" />
          Reset to Defaults
        </Button>
      </div>
    </div>
  )
}

/**
 * File: src/components/admin/dev-console/AdminCodeEditor.tsx
 * Purpose: Monaco-based code editor for ZacAi dev console
 * Features: Multiple tabs, syntax highlighting, save functionality, dirty state tracking
 */

"use client"

import { useState, useEffect, useRef } from 'react';
import Editor from '@monaco-editor/react';
import * as monaco from 'monaco-editor';
import {
  X,
  Save,
  Loader2,
  AlertCircle,
  FileCode,
} from 'lucide-react';
import { cn } from '@/lib/utils';
import { Button } from '@/components/ui/button';
import { useToast } from '@/hooks/use-toast';

interface EditorTab {
  path: string;
  content: string;
  originalContent: string;
  modified: string;
  isDirty: boolean;
  isLoading?: boolean;
}

interface AdminCodeEditorProps {
  openFiles: string[];
  activeFile?: string;
  onFileClose: (path: string) => void;
  onActiveFileChange: (path: string) => void;
  onEditorChange?: (content: string) => void;
  className?: string;
}

export function AdminCodeEditor({
  openFiles,
  activeFile,
  onFileClose,
  onActiveFileChange,
  onEditorChange,
  className,
}: AdminCodeEditorProps) {
  const [tabs, setTabs] = useState<Map<string, EditorTab>>(new Map());
  const [saving, setSaving] = useState(false);
  const editorRef = useRef<any>(null);
  const { toast } = useToast();

  // Load file content when new file is opened
  useEffect(() => {
    for (const path of openFiles) {
      if (!tabs.has(path)) {
        loadFile(path);
      }
    }

    // Remove tabs for closed files
    const newTabs = new Map(tabs);
    for (const path of tabs.keys()) {
      if (!openFiles.includes(path)) {
        newTabs.delete(path);
      }
    }
    setTabs(newTabs);
  }, [openFiles]);

  const loadFile = async (path: string) => {
    try {
      // Add loading tab
      setTabs((prev) => new Map(prev).set(path, {
        path,
        content: '',
        originalContent: '',
        modified: '',
        isDirty: false,
        isLoading: true,
      }));

      const response = await fetch(`/api/admin/dev-console/file?path=${encodeURIComponent(path)}`);

      if (!response.ok) {
        throw new Error('Failed to load file');
      }

      const data = await response.json();

      setTabs((prev) => new Map(prev).set(path, {
        path,
        content: data.content,
        originalContent: data.content,
        modified: data.modified,
        isDirty: false,
        isLoading: false,
      }));

      // Set as active if no active file
      if (!activeFile) {
        onActiveFileChange(path);
      }
    } catch (error) {
      console.error('Error loading file:', error);

      toast({
        title: 'Failed to load file',
        description: error instanceof Error ? error.message : 'Unknown error',
        variant: 'destructive',
      });

      // Remove failed tab
      setTabs((prev) => {
        const newTabs = new Map(prev);
        newTabs.delete(path);
        return newTabs;
      });
    }
  };

  const handleEditorChange = (value: string | undefined) => {
    if (!activeFile || value === undefined) return;

    setTabs((prev) => {
      const tab = prev.get(activeFile);
      if (!tab) return prev;

      const isDirty = value !== tab.originalContent;
      return new Map(prev).set(activeFile, {
        ...tab,
        content: value,
        isDirty,
      });
    });

    // Notify parent component of content change
    if (onEditorChange) {
      onEditorChange(value);
    }
  };

  const handleSave = async () => {
    if (!activeFile) return;

    const tab = tabs.get(activeFile);
    if (!tab || !tab.isDirty) return;

    try {
      setSaving(true);

      const response = await fetch('/api/admin/dev-console/file', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          path: activeFile,
          content: tab.content,
        }),
      });

      if (!response.ok) {
        throw new Error('Failed to save file');
      }

      const data = await response.json();

      // Update tab state
      setTabs((prev) => new Map(prev).set(activeFile, {
        ...tab,
        originalContent: tab.content,
        modified: data.modified,
        isDirty: false,
      }));

      toast({
        title: 'File saved',
        description: `Successfully saved ${getFileName(activeFile)}`,
      });
    } catch (error) {
      console.error('Error saving file:', error);

      toast({
        title: 'Failed to save file',
        description: error instanceof Error ? error.message : 'Unknown error',
        variant: 'destructive',
      });
    } finally {
      setSaving(false);
    }
  };

  const handleEditorMount = (editor: any) => {
    editorRef.current = editor;

    // Add keyboard shortcut for save (Ctrl/Cmd + S)
    editor.addCommand(monaco.KeyMod.CtrlCmd | monaco.KeyCode.KeyS, () => {
      handleSave();
    });
  };

  const getFileName = (path: string) => {
    return path.split('/').pop() || path;
  };

  const getLanguage = (path: string) => {
    const ext = path.split('.').pop()?.toLowerCase();

    const languageMap: Record<string, string> = {
      ts: 'typescript',
      tsx: 'typescript',
      js: 'javascript',
      jsx: 'javascript',
      json: 'json',
      md: 'markdown',
      css: 'css',
      html: 'html',
      py: 'python',
      rs: 'rust',
      go: 'go',
      yaml: 'yaml',
      yml: 'yaml',
      toml: 'toml',
      xml: 'xml',
      sql: 'sql',
      sh: 'shell',
      bash: 'shell',
    };

    return languageMap[ext || ''] || 'plaintext';
  };

  const currentTab = activeFile ? tabs.get(activeFile) : undefined;

  return (
    <div className={cn('flex flex-col h-full', className)}>
      {/* Tab Bar */}
      <div className="flex items-center bg-gray-100 dark:bg-gray-900 border-b border-gray-300 dark:border-gray-700 overflow-x-auto">
        {openFiles.length === 0 ? (
          <div className="flex items-center gap-2 px-4 py-3 text-gray-500 dark:text-gray-400">
            <FileCode className="w-4 h-4" />
            <span className="text-sm">No files open</span>
          </div>
        ) : (
          openFiles.map((path) => {
            const tab = tabs.get(path);
            const isActive = path === activeFile;

            return (
              <div
                key={path}
                className={cn(
                  'flex items-center gap-2 px-3 py-2 border-r border-gray-300 dark:border-gray-700 cursor-pointer hover:bg-gray-200 dark:hover:bg-gray-800 transition-colors',
                  isActive && 'bg-white dark:bg-gray-950 border-b-2 border-b-blue-500'
                )}
                onClick={() => onActiveFileChange(path)}
              >
                {tab?.isLoading && <Loader2 className="w-3 h-3 animate-spin" />}
                <span className="text-sm">
                  {tab?.isDirty && '● '}
                  {getFileName(path)}
                </span>
                <button
                  onClick={(e) => {
                    e.stopPropagation();
                    onFileClose(path);
                  }}
                  className="hover:bg-gray-300 dark:hover:bg-gray-700 rounded p-0.5"
                >
                  <X className="w-3 h-3" />
                </button>
              </div>
            );
          })
        )}
      </div>

      {/* Editor Toolbar */}
      {currentTab && (
        <div className="flex items-center justify-between px-4 py-2 bg-gray-50 dark:bg-gray-900 border-b border-gray-300 dark:border-gray-700">
          <div className="flex items-center gap-2 text-xs text-gray-600 dark:text-gray-400">
            <span>{getLanguage(activeFile!)}</span>
            <span>•</span>
            <span>Modified: {new Date(currentTab.modified).toLocaleString()}</span>
          </div>

          <Button
            size="sm"
            onClick={handleSave}
            disabled={!currentTab.isDirty || saving}
            variant={currentTab.isDirty ? 'default' : 'outline'}
          >
            {saving ? (
              <>
                <Loader2 className="w-3 h-3 mr-2 animate-spin" />
                Saving...
              </>
            ) : (
              <>
                <Save className="w-3 h-3 mr-2" />
                Save {currentTab.isDirty && '(Ctrl+S)'}
              </>
            )}
          </Button>
        </div>
      )}

      {/* Editor */}
      <div className="flex-1 overflow-hidden">
        {!currentTab ? (
          <div className="flex flex-col items-center justify-center h-full text-gray-500 dark:text-gray-400">
            <FileCode className="w-12 h-12 mb-4" />
            <p>Select a file to start editing</p>
          </div>
        ) : currentTab.isLoading ? (
          <div className="flex items-center justify-center h-full">
            <Loader2 className="w-8 h-8 animate-spin" />
          </div>
        ) : (
          <Editor
            value={currentTab.content}
            language={getLanguage(activeFile!)}
            onChange={handleEditorChange}
            onMount={handleEditorMount}
            theme="vs-dark"
            options={{
              minimap: { enabled: true },
              fontSize: 14,
              wordWrap: 'on',
              automaticLayout: true,
              scrollBeyondLastLine: false,
              renderWhitespace: 'selection',
              tabSize: 2,
            }}
          />
        )}
      </div>
    </div>
  );
}

/**
 * File: src/components/admin/dev-console/AdminFileTree.tsx
 * Purpose: File tree component for ZacAi dev console
 * Features: Expandable directories, file selection, lazy loading
 */

"use client"

import { useState, useEffect } from 'react';
import {
  ChevronRight,
  ChevronDown,
  Folder,
  FolderOpen,
  File,
  FileCode,
  FileJson,
  FileText,
  Loader2,
} from 'lucide-react';
import { cn } from '@/lib/utils';

interface FileItem {
  name: string;
  path: string;
  type: 'file' | 'directory';
  size: number;
  modified: string;
  children?: FileItem[];
  isExpanded?: boolean;
  isLoading?: boolean;
}

interface AdminFileTreeProps {
  onFileSelect: (path: string) => void;
  selectedPath?: string;
  className?: string;
}

export function AdminFileTree({ onFileSelect, selectedPath, className }: AdminFileTreeProps) {
  const [root, setRoot] = useState<FileItem | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    loadDirectory('');
  }, []);

  const loadDirectory = async (path: string) => {
    try {
      setLoading(true);
      setError(null);

      const response = await fetch(`/api/admin/dev-console/files?path=${encodeURIComponent(path)}`);

      if (!response.ok) {
        throw new Error('Failed to load directory');
      }

      const data = await response.json();

      if (path === '') {
        // Root directory
        setRoot({
          name: 'ZacAi Project',
          path: '',
          type: 'directory',
          size: 0,
          modified: new Date().toISOString(),
          children: data.items,
          isExpanded: true,
        });
      } else {
        // Update specific directory in tree
        updateDirectoryInTree(path, data.items);
      }
    } catch (error) {
      console.error('Error loading directory:', error);
      setError(error instanceof Error ? error.message : 'Failed to load directory');
    } finally {
      setLoading(false);
    }
  };

  const updateDirectoryInTree = (path: string, items: FileItem[]) => {
    setRoot((prevRoot) => {
      if (!prevRoot) return null;
      return updateNodeInTree(prevRoot, path, items);
    });
  };

  const updateNodeInTree = (node: FileItem, targetPath: string, items: FileItem[]): FileItem => {
    if (node.path === targetPath) {
      return {
        ...node,
        children: items,
        isExpanded: true,
        isLoading: false,
      };
    }

    if (node.children) {
      return {
        ...node,
        children: node.children.map((child) => updateNodeInTree(child, targetPath, items)),
      };
    }

    return node;
  };

  const handleDirectoryClick = async (item: FileItem) => {
    if (item.type !== 'directory') return;

    if (item.isExpanded) {
      // Collapse
      setRoot((prevRoot) => {
        if (!prevRoot) return null;
        return toggleNodeExpansion(prevRoot, item.path, false);
      });
    } else {
      // Expand and load if needed
      if (!item.children) {
        setRoot((prevRoot) => {
          if (!prevRoot) return null;
          return setNodeLoading(prevRoot, item.path, true);
        });

        await loadDirectory(item.path);
      } else {
        setRoot((prevRoot) => {
          if (!prevRoot) return null;
          return toggleNodeExpansion(prevRoot, item.path, true);
        });
      }
    }
  };

  const toggleNodeExpansion = (node: FileItem, targetPath: string, expanded: boolean): FileItem => {
    if (node.path === targetPath) {
      return { ...node, isExpanded: expanded };
    }

    if (node.children) {
      return {
        ...node,
        children: node.children.map((child) => toggleNodeExpansion(child, targetPath, expanded)),
      };
    }

    return node;
  };

  const setNodeLoading = (node: FileItem, targetPath: string, loading: boolean): FileItem => {
    if (node.path === targetPath) {
      return { ...node, isLoading: loading };
    }

    if (node.children) {
      return {
        ...node,
        children: node.children.map((child) => setNodeLoading(child, targetPath, loading)),
      };
    }

    return node;
  };

  const getFileIcon = (filename: string) => {
    const ext = filename.split('.').pop()?.toLowerCase();

    switch (ext) {
      case 'json':
        return FileJson;
      case 'ts':
      case 'tsx':
      case 'js':
      case 'jsx':
      case 'py':
      case 'rs':
      case 'go':
        return FileCode;
      case 'md':
      case 'txt':
        return FileText;
      default:
        return File;
    }
  };

  const renderTreeNode = (item: FileItem, level: number = 0) => {
    const isDirectory = item.type === 'directory';
    const isSelected = item.path === selectedPath;
    const Icon = isDirectory
      ? item.isExpanded
        ? FolderOpen
        : Folder
      : getFileIcon(item.name);

    return (
      <div key={item.path}>
        <div
          className={cn(
            'flex items-center gap-2 px-2 py-1 cursor-pointer hover:bg-gray-100 dark:hover:bg-gray-800 rounded',
            isSelected && 'bg-blue-100 dark:bg-blue-900',
            'transition-colors'
          )}
          style={{ paddingLeft: `${level * 16 + 8}px` }}
          onClick={() => {
            if (isDirectory) {
              handleDirectoryClick(item);
            } else {
              onFileSelect(item.path);
            }
          }}
        >
          {isDirectory && (
            <span className="w-4 h-4 flex items-center justify-center">
              {item.isLoading ? (
                <Loader2 className="w-3 h-3 animate-spin" />
              ) : item.isExpanded ? (
                <ChevronDown className="w-3 h-3" />
              ) : (
                <ChevronRight className="w-3 h-3" />
              )}
            </span>
          )}
          {!isDirectory && <span className="w-4" />}
          <Icon className="w-4 h-4 flex-shrink-0" />
          <span className="text-sm truncate">{item.name}</span>
        </div>

        {isDirectory && item.isExpanded && item.children && (
          <div>
            {item.children.map((child) => renderTreeNode(child, level + 1))}
          </div>
        )}
      </div>
    );
  };

  if (loading && !root) {
    return (
      <div className={cn('flex items-center justify-center p-4', className)}>
        <Loader2 className="w-6 h-6 animate-spin" />
      </div>
    );
  }

  if (error) {
    return (
      <div className={cn('p-4 text-red-600 dark:text-red-400', className)}>
        <p className="font-semibold">Error loading file tree</p>
        <p className="text-sm">{error}</p>
      </div>
    );
  }

  if (!root) {
    return null;
  }

  return (
    <div className={cn('overflow-y-auto', className)}>
      {renderTreeNode(root)}
    </div>
  );
}

/**
 * File: src/components/admin/dev-console/GitHubControls.tsx
 * Purpose: GitHub branch management controls for dev console
 * 
 * Features:
 * - Create experimental branches
 * - Create backup branches
 * - List and manage branches
 * - Commit changes with reasoning
 * - Create pull requests
 */

"use client";

import React, { useState, useEffect } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";

interface GitHubControlsProps {
  currentFile?: string;
  fileContent?: string;
}

interface Branch {
  name: string;
  sha: string;
  protected: boolean;
}

export function GitHubControls({ currentFile, fileContent }: GitHubControlsProps) {
  const [branches, setBranches] = useState<Branch[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Branch creation state
  const [featureName, setFeatureName] = useState("");
  const [description, setDescription] = useState("");
  const [version, setVersion] = useState("");

  // Commit state
  const [commitBranch, setCommitBranch] = useState("");
  const [commitMessage, setCommitMessage] = useState("");
  const [reasoning, setReasoning] = useState("");

  // PR state
  const [prBranch, setPrBranch] = useState("");
  const [prTitle, setPrTitle] = useState("");
  const [prReasoning, setPrReasoning] = useState("");

  useEffect(() => {
    loadBranches();
  }, []);

  async function loadBranches() {
    try {
      setLoading(true);
      setError(null);

      const response = await fetch("/api/admin/dev-console/github/branch");
      if (!response.ok) {
        const data = await response.json();
        throw new Error(data.error || "Failed to load branches");
      }

      const data = await response.json();
      setBranches(data.branches || []);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Unknown error");
    } finally {
      setLoading(false);
    }
  }

  async function createExperimentalBranch() {
    if (!featureName.trim()) {
      alert("Please enter a feature name");
      return;
    }

    try {
      setLoading(true);
      setError(null);

      const response = await fetch("/api/admin/dev-console/github/branch", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          action: "experimental",
          featureName: featureName.trim().replace(/\s+/g, "-").toLowerCase(),
          description,
        }),
      });

      if (!response.ok) {
        const data = await response.json();
        throw new Error(data.error || "Failed to create branch");
      }

      const data = await response.json();
      alert(`Created branch: ${data.branch}`);
      setFeatureName("");
      setDescription("");
      loadBranches();
    } catch (err) {
      alert(err instanceof Error ? err.message : "Unknown error");
    } finally {
      setLoading(false);
    }
  }

  async function createBackupBranch() {
    try {
      setLoading(true);
      setError(null);

      const response = await fetch("/api/admin/dev-console/github/branch", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          action: "backup",
          version: version || undefined,
        }),
      });

      if (!response.ok) {
        const data = await response.json();
        throw new Error(data.error || "Failed to create backup");
      }

      const data = await response.json();
      alert(`Created backup: ${data.branch}`);
      setVersion("");
      loadBranches();
    } catch (err) {
      alert(err instanceof Error ? err.message : "Unknown error");
    } finally {
      setLoading(false);
    }
  }

  async function commitChanges() {
    if (!commitBranch || !commitMessage) {
      alert("Branch and commit message are required");
      return;
    }

    if (!currentFile || !fileContent) {
      alert("No file is currently open to commit");
      return;
    }

    try {
      setLoading(true);
      setError(null);

      const response = await fetch("/api/admin/dev-console/github/commit", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          branch: commitBranch,
          message: commitMessage,
          files: [
            {
              path: currentFile,
              content: fileContent,
            },
          ],
          reasoning: reasoning || undefined,
        }),
      });

      if (!response.ok) {
        const data = await response.json();
        throw new Error(data.error || "Failed to commit");
      }

      const data = await response.json();
      alert(`Committed successfully: ${data.sha}`);
      setCommitMessage("");
      setReasoning("");
    } catch (err) {
      alert(err instanceof Error ? err.message : "Unknown error");
    } finally {
      setLoading(false);
    }
  }

  async function createPullRequest() {
    if (!prBranch || !prTitle || !prReasoning) {
      alert("Branch, title, and reasoning are required");
      return;
    }

    try {
      setLoading(true);
      setError(null);

      const response = await fetch("/api/admin/dev-console/github/pr", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          branch: prBranch,
          featureName: prTitle,
          reasoning: prReasoning,
        }),
      });

      if (!response.ok) {
        const data = await response.json();
        throw new Error(data.error || "Failed to create PR");
      }

      const data = await response.json();
      alert(`Created PR #${data.prNumber}: ${data.prUrl}`);
      setPrTitle("");
      setPrReasoning("");
      window.open(data.prUrl, "_blank");
    } catch (err) {
      alert(err instanceof Error ? err.message : "Unknown error");
    } finally {
      setLoading(false);
    }
  }

  async function deleteBranch(branchName: string) {
    if (!confirm(`Delete branch ${branchName}?`)) return;

    try {
      setLoading(true);

      const response = await fetch(
        `/api/admin/dev-console/github/branch?branch=${encodeURIComponent(branchName)}`,
        { method: "DELETE" }
      );

      if (!response.ok) {
        const data = await response.json();
        throw new Error(data.error || "Failed to delete branch");
      }

      alert(`Deleted branch: ${branchName}`);
      loadBranches();
    } catch (err) {
      alert(err instanceof Error ? err.message : "Unknown error");
    } finally {
      setLoading(false);
    }
  }

  return (
    <Card className="w-full">
      <CardHeader>
        <CardTitle>GitHub Operations</CardTitle>
        <CardDescription>
          Manage experimental branches, commits, and pull requests for ZacAi self-learning
        </CardDescription>
      </CardHeader>
      <CardContent>
        {error && (
          <div className="mb-4 p-3 bg-red-50 border border-red-200 rounded text-red-700 text-sm">
            {error}
          </div>
        )}

        <Tabs defaultValue="branches" className="w-full">
          <TabsList className="grid w-full grid-cols-4">
            <TabsTrigger value="branches">Branches</TabsTrigger>
            <TabsTrigger value="commit">Commit</TabsTrigger>
            <TabsTrigger value="pr">Pull Request</TabsTrigger>
            <TabsTrigger value="backup">Backup</TabsTrigger>
          </TabsList>

          {/* Branches Tab */}
          <TabsContent value="branches" className="space-y-4">
            <div className="space-y-3">
              <div className="flex gap-2">
                <Input
                  placeholder="Feature name (e.g., optimize-inference)"
                  value={featureName}
                  onChange={(e) => setFeatureName(e.target.value)}
                />
                <Button onClick={createExperimentalBranch} disabled={loading}>
                  Create Experimental
                </Button>
              </div>
              <Input
                placeholder="Description (optional)"
                value={description}
                onChange={(e) => setDescription(e.target.value)}
              />
            </div>

            <div className="mt-4">
              <div className="flex items-center justify-between mb-2">
                <h4 className="font-semibold">Experimental Branches</h4>
                <Button variant="outline" size="sm" onClick={loadBranches} disabled={loading}>
                  Refresh
                </Button>
              </div>

              {branches.length === 0 && !loading && (
                <p className="text-sm text-muted-foreground">No experimental branches found</p>
              )}

              <div className="space-y-2">
                {branches.map((branch) => (
                  <div
                    key={branch.name}
                    className="flex items-center justify-between p-2 border rounded"
                  >
                    <div className="flex-1">
                      <p className="font-mono text-sm">{branch.name}</p>
                      <p className="text-xs text-muted-foreground">{branch.sha.slice(0, 7)}</p>
                    </div>
                    <div className="flex gap-2">
                      {branch.protected && <Badge variant="secondary">Protected</Badge>}
                      <Button
                        variant="ghost"
                        size="sm"
                        onClick={() => deleteBranch(branch.name)}
                        disabled={loading || branch.protected}
                      >
                        Delete
                      </Button>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </TabsContent>

          {/* Commit Tab */}
          <TabsContent value="commit" className="space-y-4">
            <div className="space-y-3">
              <div>
                <Label>Branch</Label>
                <Input
                  placeholder="Branch name (e.g., zacai-experiment-...)"
                  value={commitBranch}
                  onChange={(e) => setCommitBranch(e.target.value)}
                />
              </div>
              <div>
                <Label>Commit Message</Label>
                <Input
                  placeholder="Brief description of changes"
                  value={commitMessage}
                  onChange={(e) => setCommitMessage(e.target.value)}
                />
              </div>
              <div>
                <Label>Reasoning (Optional)</Label>
                <Textarea
                  placeholder="Explain why these changes were made..."
                  value={reasoning}
                  onChange={(e) => setReasoning(e.target.value)}
                  rows={4}
                />
              </div>
              {currentFile && (
                <p className="text-sm text-muted-foreground">
                  Will commit: <span className="font-mono">{currentFile}</span>
                </p>
              )}
              <Button onClick={commitChanges} disabled={loading || !currentFile}>
                Commit to Branch
              </Button>
            </div>
          </TabsContent>

          {/* PR Tab */}
          <TabsContent value="pr" className="space-y-4">
            <div className="space-y-3">
              <div>
                <Label>Branch</Label>
                <Input
                  placeholder="Branch to create PR from"
                  value={prBranch}
                  onChange={(e) => setPrBranch(e.target.value)}
                />
              </div>
              <div>
                <Label>Feature Title</Label>
                <Input
                  placeholder="Name of the feature"
                  value={prTitle}
                  onChange={(e) => setPrTitle(e.target.value)}
                />
              </div>
              <div>
                <Label>Reasoning</Label>
                <Textarea
                  placeholder="Explain the purpose and benefits of this feature..."
                  value={prReasoning}
                  onChange={(e) => setPrReasoning(e.target.value)}
                  rows={6}
                />
              </div>
              <Button onClick={createPullRequest} disabled={loading}>
                Create Pull Request
              </Button>
            </div>
          </TabsContent>

          {/* Backup Tab */}
          <TabsContent value="backup" className="space-y-4">
            <div className="space-y-3">
              <div>
                <Label>Version (Optional)</Label>
                <Input
                  placeholder="e.g., v0.0.5"
                  value={version}
                  onChange={(e) => setVersion(e.target.value)}
                />
              </div>
              <Button onClick={createBackupBranch} disabled={loading}>
                Create Backup Branch
              </Button>
              <p className="text-sm text-muted-foreground">
                Creates a snapshot of the current main branch for rollback purposes.
              </p>
            </div>
          </TabsContent>
        </Tabs>
      </CardContent>
    </Card>
  );
}

'use client'

// Inspired by react-hot-toast library
import * as React from 'react'

import type { ToastActionElement, ToastProps } from '@/components/ui/toast'

const TOAST_LIMIT = 1
const TOAST_REMOVE_DELAY = 1000000

type ToasterToast = ToastProps & {
  id: string
  title?: React.ReactNode
  description?: React.ReactNode
  action?: ToastActionElement
}

const actionTypes = {
  ADD_TOAST: 'ADD_TOAST',
  UPDATE_TOAST: 'UPDATE_TOAST',
  DISMISS_TOAST: 'DISMISS_TOAST',
  REMOVE_TOAST: 'REMOVE_TOAST',
} as const

let count = 0

function genId() {
  count = (count + 1) % Number.MAX_SAFE_INTEGER
  return count.toString()
}

type ActionType = typeof actionTypes

type Action =
  | {
      type: ActionType['ADD_TOAST']
      toast: ToasterToast
    }
  | {
      type: ActionType['UPDATE_TOAST']
      toast: Partial<ToasterToast>
    }
  | {
      type: ActionType['DISMISS_TOAST']
      toastId?: ToasterToast['id']
    }
  | {
      type: ActionType['REMOVE_TOAST']
      toastId?: ToasterToast['id']
    }

interface State {
  toasts: ToasterToast[]
}

const toastTimeouts = new Map<string, ReturnType<typeof setTimeout>>()

const addToRemoveQueue = (toastId: string) => {
  if (toastTimeouts.has(toastId)) {
    return
  }

  const timeout = setTimeout(() => {
    toastTimeouts.delete(toastId)
    dispatch({
      type: 'REMOVE_TOAST',
      toastId: toastId,
    })
  }, TOAST_REMOVE_DELAY)

  toastTimeouts.set(toastId, timeout)
}

export const reducer = (state: State, action: Action): State => {
  switch (action.type) {
    case 'ADD_TOAST':
      return {
        ...state,
        toasts: [action.toast, ...state.toasts].slice(0, TOAST_LIMIT),
      }

    case 'UPDATE_TOAST':
      return {
        ...state,
        toasts: state.toasts.map((t) =>
          t.id === action.toast.id ? { ...t, ...action.toast } : t,
        ),
      }

    case 'DISMISS_TOAST': {
      const { toastId } = action

      // ! Side effects ! - This could be extracted into a dismissToast() action,
      // but I'll keep it here for simplicity
      if (toastId) {
        addToRemoveQueue(toastId)
      } else {
        state.toasts.forEach((toast) => {
          addToRemoveQueue(toast.id)
        })
      }

      return {
        ...state,
        toasts: state.toasts.map((t) =>
          t.id === toastId || toastId === undefined
            ? {
                ...t,
                open: false,
              }
            : t,
        ),
      }
    }
    case 'REMOVE_TOAST':
      if (action.toastId === undefined) {
        return {
          ...state,
          toasts: [],
        }
      }
      return {
        ...state,
        toasts: state.toasts.filter((t) => t.id !== action.toastId),
      }
  }
}

const listeners: Array<(state: State) => void> = []

let memoryState: State = { toasts: [] }

function dispatch(action: Action) {
  memoryState = reducer(memoryState, action)
  listeners.forEach((listener) => {
    listener(memoryState)
  })
}

type Toast = Omit<ToasterToast, 'id'>

function toast({ ...props }: Toast) {
  const id = genId()

  const update = (props: ToasterToast) =>
    dispatch({
      type: 'UPDATE_TOAST',
      toast: { ...props, id },
    })
  const dismiss = () => dispatch({ type: 'DISMISS_TOAST', toastId: id })

  dispatch({
    type: 'ADD_TOAST',
    toast: {
      ...props,
      id,
      open: true,
      onOpenChange: (open) => {
        if (!open) dismiss()
      },
    },
  })

  return {
    id: id,
    dismiss,
    update,
  }
}

function useToast() {
  const [state, setState] = React.useState<State>(memoryState)

  React.useEffect(() => {
    listeners.push(setState)
    return () => {
      const index = listeners.indexOf(setState)
      if (index > -1) {
        listeners.splice(index, 1)
      }
    }
  }, [state])

  return {
    ...state,
    toast,
    dismiss: (toastId?: string) => dispatch({ type: 'DISMISS_TOAST', toastId }),
  }
}

export { useToast, toast }

/**
 * AI Assistant for IDE
 * Provides context-aware AI assistance for coding
 */

export interface IDEContext {
  currentFile?: {
    path: string;
    content: string;
    language: string;
    cursorPosition?: { line: number; column: number };
    selection?: string;
  };
  openFiles: Array<{
    path: string;
    content: string;
    language: string;
  }>;
  projectFiles: string[];
  terminalOutput?: string;
  errors?: Array<{
    file: string;
    line: number;
    message: string;
  }>;
}

export interface AIMessage {
  id: string;
  role: 'user' | 'assistant' | 'system';
  content: string;
  timestamp: Date;
  codeBlocks?: Array<{
    language: string;
    code: string;
    filename?: string;
  }>;
  actions?: Array<{
    type: 'create' | 'update' | 'delete' | 'open';
    file: string;
    content?: string;
  }>;
}

export interface AIResponse {
  text: string;
  codeBlocks: Array<{
    language: string;
    code: string;
    filename?: string;
  }>;
  actions: Array<{
    type: 'create' | 'update' | 'delete' | 'open';
    file: string;
    content?: string;
  }>;
  domains: string[];
  confidence: number;
  metadata?: any;
}

export class AIAssistant {
  private sessionId: string | null = null;
  private apiEndpoint = '/api/chat';

  /**
   * Initialize AI session
   */
  async initialize(): Promise<string> {
    try {
      const response = await fetch(this.apiEndpoint, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'initialize' }),
      });

      if (!response.ok) {
        throw new Error('Failed to initialize AI session');
      }

      const data = await response.json();
      this.sessionId = data.sessionId;
      return this.sessionId;
    } catch (error) {
      console.error('AI initialization error:', error);
      throw error;
    }
  }

  /**
   * Send a message to the AI with IDE context
   */
  async sendMessage(message: string, context: IDEContext): Promise<AIResponse> {
    if (!this.sessionId) {
      await this.initialize();
    }

    try {
      // Enhance prompt with IDE context
      const enhancedPrompt = this.buildContextualPrompt(message, context);

      const response = await fetch(this.apiEndpoint, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          action: 'chat',
          message: enhancedPrompt,
          sessionId: this.sessionId,
        }),
      });

      if (!response.ok) {
        throw new Error('Failed to get AI response');
      }

      const data = await response.json();

      // Parse response for code blocks and actions
      const codeBlocks = this.extractCodeBlocks(data.text);
      const actions = this.extractActions(data.text, context);

      return {
        text: data.text,
        codeBlocks,
        actions,
        domains: data.domains || [],
        confidence: data.confidence || 0,
        metadata: data.metadata,
      };
    } catch (error) {
      console.error('AI message error:', error);
      throw error;
    }
  }

  /**
   * Build a contextual prompt with IDE information
   */
  private buildContextualPrompt(message: string, context: IDEContext): string {
    let prompt = `[IDE Context]\n`;

    // Add current file context
    if (context.currentFile) {
      prompt += `Current File: ${context.currentFile.path}\n`;
      prompt += `Language: ${context.currentFile.language}\n`;

      if (context.currentFile.selection) {
        prompt += `\nSelected Code:\n\`\`\`${context.currentFile.language}\n${context.currentFile.selection}\n\`\`\`\n`;
      } else if (context.currentFile.content) {
        // Include first 100 lines or 5000 chars of current file
        const contentPreview = context.currentFile.content
          .split('\n')
          .slice(0, 100)
          .join('\n')
          .slice(0, 5000);
        prompt += `\nCurrent File Content:\n\`\`\`${context.currentFile.language}\n${contentPreview}\n\`\`\`\n`;
      }
    }

    // Add project files list
    if (context.projectFiles.length > 0) {
      prompt += `\nProject Files (${context.projectFiles.length}):\n`;
      prompt += context.projectFiles.slice(0, 20).join('\n');
      if (context.projectFiles.length > 20) {
        prompt += `\n... and ${context.projectFiles.length - 20} more files`;
      }
      prompt += '\n';
    }

    // Add errors if any
    if (context.errors && context.errors.length > 0) {
      prompt += `\nCurrent Errors:\n`;
      context.errors.forEach((error) => {
        prompt += `- ${error.file}:${error.line}: ${error.message}\n`;
      });
    }

    prompt += `\n[User Request]\n${message}\n`;

    return prompt;
  }

  /**
   * Extract code blocks from AI response
   */
  private extractCodeBlocks(text: string): Array<{
    language: string;
    code: string;
    filename?: string;
  }> {
    const codeBlocks: Array<{ language: string; code: string; filename?: string }> = [];

    // Match code blocks with language and optional filename
    const codeBlockRegex = /```(\w+)(?:\s+(.+?))?\n([\s\S]*?)```/g;
    let match;

    while ((match = codeBlockRegex.exec(text)) !== null) {
      const [, language, filename, code] = match;
      codeBlocks.push({
        language: language || 'plaintext',
        code: code.trim(),
        filename: filename?.trim(),
      });
    }

    return codeBlocks;
  }

  /**
   * Extract file actions from AI response
   */
  private extractActions(
    text: string,
    context: IDEContext
  ): Array<{
    type: 'create' | 'update' | 'delete' | 'open';
    file: string;
    content?: string;
  }> {
    const actions: Array<{
      type: 'create' | 'update' | 'delete' | 'open';
      file: string;
      content?: string;
    }> = [];

    // Look for explicit action commands
    const actionPatterns = [
      /create file `([^`]+)`/gi,
      /update file `([^`]+)`/gi,
      /delete file `([^`]+)`/gi,
      /open file `([^`]+)`/gi,
    ];

    const codeBlocks = this.extractCodeBlocks(text);

    // If code blocks have filenames, suggest creating/updating them
    codeBlocks.forEach((block) => {
      if (block.filename) {
        const existsInProject = context.projectFiles.some((f) =>
          f.endsWith(block.filename!)
        );
        actions.push({
          type: existsInProject ? 'update' : 'create',
          file: block.filename,
          content: block.code,
        });
      }
    });

    return actions;
  }

  /**
   * Quick actions for common IDE tasks
   */
  async explainCode(code: string, language: string): Promise<AIResponse> {
    return this.sendMessage(`Explain this ${language} code:\n\`\`\`${language}\n${code}\n\`\`\``, {
      openFiles: [],
      projectFiles: [],
      currentFile: {
        path: 'selection',
        content: code,
        language,
      },
    });
  }

  async fixCode(code: string, language: string, error?: string): Promise<AIResponse> {
    const prompt = error
      ? `Fix this ${language} code that's producing the error: "${error}"\n\`\`\`${language}\n${code}\n\`\`\``
      : `Fix any issues in this ${language} code:\n\`\`\`${language}\n${code}\n\`\`\``;

    return this.sendMessage(prompt, {
      openFiles: [],
      projectFiles: [],
      currentFile: {
        path: 'selection',
        content: code,
        language,
      },
    });
  }

  async optimizeCode(code: string, language: string): Promise<AIResponse> {
    return this.sendMessage(
      `Optimize this ${language} code for better performance and readability:\n\`\`\`${language}\n${code}\n\`\`\``,
      {
        openFiles: [],
        projectFiles: [],
        currentFile: {
          path: 'selection',
          content: code,
          language,
        },
      }
    );
  }

  async generateCode(description: string, language: string): Promise<AIResponse> {
    return this.sendMessage(`Generate ${language} code for: ${description}`, {
      openFiles: [],
      projectFiles: [],
      currentFile: {
        path: 'new-file',
        content: '',
        language,
      },
    });
  }

  async addDocumentation(code: string, language: string): Promise<AIResponse> {
    return this.sendMessage(
      `Add comprehensive documentation/comments to this ${language} code:\n\`\`\`${language}\n${code}\n\`\`\``,
      {
        openFiles: [],
        projectFiles: [],
        currentFile: {
          path: 'selection',
          content: code,
          language,
        },
      }
    );
  }

  async generateTests(code: string, language: string): Promise<AIResponse> {
    return this.sendMessage(
      `Generate unit tests for this ${language} code:\n\`\`\`${language}\n${code}\n\`\`\``,
      {
        openFiles: [],
        projectFiles: [],
        currentFile: {
          path: 'selection',
          content: code,
          language,
        },
      }
    );
  }

  async refactorCode(code: string, language: string, instructions: string): Promise<AIResponse> {
    return this.sendMessage(
      `Refactor this ${language} code: ${instructions}\n\`\`\`${language}\n${code}\n\`\`\``,
      {
        openFiles: [],
        projectFiles: [],
        currentFile: {
          path: 'selection',
          content: code,
          language,
        },
      }
    );
  }

  /**
   * Get session ID
   */
  getSessionId(): string | null {
    return this.sessionId;
  }

  /**
   * Reset session
   */
  async resetSession(): Promise<void> {
    this.sessionId = null;
    await this.initialize();
  }
}

