/**
 * Command Processor for IDE Terminal
 * Handles shell-like commands in the browser
 */

export interface CommandResult {
  output: string;
  exitCode: number;
  error?: string;
}

export interface CommandContext {
  fs: CommandFileSystem;
  currentPath: string;
  environment: Record<string, string>;
}

export interface CommandFileSystemEntry {
  name: string;
  path: string;
  type: 'file' | 'directory';
  metadata?: {
    size?: number;
    modified?: number;
  };
}

export interface CommandFileSystem {
  read(path: string): Promise<string>;
  write(path: string, content: string): Promise<void>;
  mkdir(path: string): Promise<void>;
  delete(path: string): Promise<void>;
  list(path: string): Promise<CommandFileSystemEntry[]>;
  exists(path: string): Promise<boolean>;
  search(query: string): Promise<CommandFileSystemEntry[]>;
}

export class CommandProcessor {
  private context: CommandContext;
  private commandHistory: string[] = [];
  private historyIndex = -1;

  constructor(fs: CommandFileSystem) {
    this.context = {
      fs,
      currentPath: '/',
      environment: {
        HOME: '/',
        PATH: '/bin:/usr/bin:/usr/local/bin',
        USER: 'zacai',
        SHELL: '/bin/bash',
      },
    };
  }

  async executeCommand(commandLine: string): Promise<CommandResult> {
    if (!commandLine.trim()) {
      return { output: '', exitCode: 0 };
    }

    // Add to history
    this.commandHistory.push(commandLine);
    this.historyIndex = this.commandHistory.length;

    // Parse command
    const parts = this.parseCommand(commandLine);
    const command = parts[0];
    const args = parts.slice(1);

    try {
      // Route to appropriate handler
      switch (command) {
        case 'ls':
          return await this.handleLs(args);
        case 'cd':
          return await this.handleCd(args);
        case 'pwd':
          return await this.handlePwd();
        case 'cat':
          return await this.handleCat(args);
        case 'mkdir':
          return await this.handleMkdir(args);
        case 'touch':
          return await this.handleTouch(args);
        case 'rm':
          return await this.handleRm(args);
        case 'echo':
          return await this.handleEcho(args);
        case 'clear':
          return { output: '\x1bc', exitCode: 0 };
        case 'help':
          return await this.handleHelp();
        case 'tree':
          return await this.handleTree(args);
        case 'find':
          return await this.handleFind(args);
        case 'grep':
          return await this.handleGrep(args);
        case 'node':
          return await this.handleNode(args);
        case 'npm':
          return await this.handleNpm(args);
        case 'git':
          return await this.handleGit(args);
        default:
          return {
            output: `bash: ${command}: command not found\n`,
            exitCode: 127,
            error: 'Command not found',
          };
      }
    } catch (error) {
      return {
        output: `Error: ${error instanceof Error ? error.message : String(error)}\n`,
        exitCode: 1,
        error: String(error),
      };
    }
  }

  private parseCommand(commandLine: string): string[] {
    // Simple parsing - can be enhanced for quotes, pipes, etc.
    return commandLine.trim().split(/\s+/);
  }

  private resolvePath(path: string): string {
    if (path.startsWith('/')) {
      return path;
    }
    if (path === '~') {
      return this.context.environment.HOME;
    }
    if (path.startsWith('~/')) {
      return this.context.environment.HOME + path.slice(1);
    }
    if (path === '.') {
      return this.context.currentPath;
    }
    if (path === '..') {
      const parts = this.context.currentPath.split('/').filter(Boolean);
      parts.pop();
      return '/' + parts.join('/');
    }
    // Relative path
    const base = this.context.currentPath === '/' ? '' : this.context.currentPath;
    return base + '/' + path;
  }

  private async handleLs(args: string[]): Promise<CommandResult> {
    const showAll = args.includes('-a') || args.includes('-la') || args.includes('-al');
    const longFormat = args.includes('-l') || args.includes('-la') || args.includes('-al');
    const path = args.find((arg) => !arg.startsWith('-')) || this.context.currentPath;
    const resolvedPath = this.resolvePath(path);

    try {
      const items = await this.context.fs.list(resolvedPath);

      if (items.length === 0) {
        return { output: '', exitCode: 0 };
      }

      let output = '';
      if (longFormat) {
        for (const item of items) {
          const type = item.type === 'directory' ? 'd' : '-';
          const perms = 'rwxr-xr-x';
          const size = item.metadata?.size || 0;
          const date = item.metadata?.modified
            ? new Date(item.metadata.modified).toLocaleDateString()
            : 'Unknown';
          output += `${type}${perms} 1 zacai zacai ${size.toString().padStart(8)} ${date} ${item.name}\n`;
        }
      } else {
        output = items.map((item) => item.name).join('  ') + '\n';
      }

      return { output, exitCode: 0 };
    } catch (error) {
      return {
        output: `ls: cannot access '${path}': No such file or directory\n`,
        exitCode: 2,
        error: String(error),
      };
    }
  }

  private async handleCd(args: string[]): Promise<CommandResult> {
    const path = args[0] || this.context.environment.HOME;
    const resolvedPath = this.resolvePath(path);

    try {
      const exists = await this.context.fs.exists(resolvedPath);
      if (!exists) {
        return {
          output: `cd: ${path}: No such file or directory\n`,
          exitCode: 1,
          error: 'Directory not found',
        };
      }

      // Check if it's a directory
      const items = await this.context.fs.list(resolvedPath.split('/').slice(0, -1).join('/') || '/');
      const item = items.find((i) => i.path === resolvedPath);

      if (item && item.type !== 'directory') {
        return {
          output: `cd: ${path}: Not a directory\n`,
          exitCode: 1,
          error: 'Not a directory',
        };
      }

      this.context.currentPath = resolvedPath;
      return { output: '', exitCode: 0 };
    } catch (error) {
      return {
        output: `cd: ${path}: No such file or directory\n`,
        exitCode: 1,
        error: String(error),
      };
    }
  }

  private async handlePwd(): Promise<CommandResult> {
    return {
      output: this.context.currentPath + '\n',
      exitCode: 0,
    };
  }

  private async handleCat(args: string[]): Promise<CommandResult> {
    if (args.length === 0) {
      return {
        output: 'cat: missing file operand\n',
        exitCode: 1,
        error: 'Missing file operand',
      };
    }

    let output = '';
    for (const arg of args) {
      const path = this.resolvePath(arg);
      try {
        const content = await this.context.fs.read(path);
        output += content + '\n';
      } catch (error) {
        output += `cat: ${arg}: No such file or directory\n`;
      }
    }

    return { output, exitCode: 0 };
  }

  private async handleMkdir(args: string[]): Promise<CommandResult> {
    if (args.length === 0) {
      return {
        output: 'mkdir: missing operand\n',
        exitCode: 1,
        error: 'Missing operand',
      };
    }

    for (const arg of args) {
      if (arg.startsWith('-')) continue; // Skip flags
      const path = this.resolvePath(arg);
      try {
        await this.context.fs.mkdir(path);
      } catch (error) {
        return {
          output: `mkdir: cannot create directory '${arg}': ${error}\n`,
          exitCode: 1,
          error: String(error),
        };
      }
    }

    return { output: '', exitCode: 0 };
  }

  private async handleTouch(args: string[]): Promise<CommandResult> {
    if (args.length === 0) {
      return {
        output: 'touch: missing file operand\n',
        exitCode: 1,
        error: 'Missing file operand',
      };
    }

    for (const arg of args) {
      const path = this.resolvePath(arg);
      try {
        const exists = await this.context.fs.exists(path);
        if (!exists) {
          await this.context.fs.write(path, '');
        }
      } catch (error) {
        return {
          output: `touch: cannot touch '${arg}': ${error}\n`,
          exitCode: 1,
          error: String(error),
        };
      }
    }

    return { output: '', exitCode: 0 };
  }

  private async handleRm(args: string[]): Promise<CommandResult> {
    if (args.length === 0) {
      return {
        output: 'rm: missing operand\n',
        exitCode: 1,
        error: 'Missing operand',
      };
    }

    const recursive = args.includes('-r') || args.includes('-rf');
    const files = args.filter((arg) => !arg.startsWith('-'));

    for (const file of files) {
      const path = this.resolvePath(file);
      try {
        await this.context.fs.delete(path);
      } catch (error) {
        return {
          output: `rm: cannot remove '${file}': ${error}\n`,
          exitCode: 1,
          error: String(error),
        };
      }
    }

    return { output: '', exitCode: 0 };
  }

  private async handleEcho(args: string[]): Promise<CommandResult> {
    const output = args.join(' ') + '\n';
    return { output, exitCode: 0 };
  }

  private async handleHelp(): Promise<CommandResult> {
    const output = `
ZacAi IDE Terminal - Available Commands:

File System:
  ls [-l] [path]       List directory contents
  cd [path]            Change directory
  pwd                  Print working directory
  cat <file>           Display file contents
  mkdir <dir>          Create directory
  touch <file>         Create empty file
  rm [-r] <file>       Remove file or directory
  tree [path]          Display directory tree
  find <name>          Search for files

Text Processing:
  echo <text>          Print text
  grep <pattern> <file> Search for pattern in file

Development:
  node <file>          Execute JavaScript file
  npm <command>        NPM package manager
  git <command>        Git version control

System:
  clear                Clear terminal
  help                 Show this help message

For more information, type: man <command>
`;
    return { output, exitCode: 0 };
  }

  private async handleTree(args: string[]): Promise<CommandResult> {
    const path = args[0] || this.context.currentPath;
    const resolvedPath = this.resolvePath(path);

    const buildTree = async (dirPath: string, prefix = '', isLast = true): Promise<string> => {
      let output = '';
      try {
        const items = await this.context.fs.list(dirPath);
        items.sort((a, b) => {
          if (a.type === 'directory' && b.type !== 'directory') return -1;
          if (a.type !== 'directory' && b.type === 'directory') return 1;
          return a.name.localeCompare(b.name);
        });

        for (let i = 0; i < items.length; i++) {
          const item = items[i];
          const isLastItem = i === items.length - 1;
          const connector = isLastItem ? '└── ' : '├── ';
          const icon = item.type === 'directory' ? '📁 ' : '📄 ';

          output += prefix + connector + icon + item.name + '\n';

          if (item.type === 'directory') {
            const newPrefix = prefix + (isLastItem ? '    ' : '│   ');
            output += await buildTree(item.path, newPrefix, isLastItem);
          }
        }
      } catch (error) {
        // Silently ignore errors in subdirectories
      }
      return output;
    };

    try {
      let output = resolvedPath + '\n';
      output += await buildTree(resolvedPath);
      return { output, exitCode: 0 };
    } catch (error) {
      return {
        output: `tree: ${path}: No such directory\n`,
        exitCode: 1,
        error: String(error),
      };
    }
  }

  private async handleFind(args: string[]): Promise<CommandResult> {
    if (args.length === 0) {
      return {
        output: 'find: missing search term\n',
        exitCode: 1,
        error: 'Missing search term',
      };
    }

    const searchTerm = args[0];
    try {
      const results = await this.context.fs.search(searchTerm);
      const output = results.map((r) => r.path).join('\n') + (results.length > 0 ? '\n' : '');
      return { output, exitCode: 0 };
    } catch (error) {
      return {
        output: `find: search failed: ${error}\n`,
        exitCode: 1,
        error: String(error),
      };
    }
  }

  private async handleGrep(args: string[]): Promise<CommandResult> {
    if (args.length < 2) {
      return {
        output: 'grep: missing pattern or file\n',
        exitCode: 1,
        error: 'Missing arguments',
      };
    }

    const pattern = args[0];
    const filePath = this.resolvePath(args[1]);

    try {
      const content = await this.context.fs.read(filePath);
      const lines = content.split('\n');
      const matches = lines.filter((line) => line.includes(pattern));
      const output = matches.join('\n') + (matches.length > 0 ? '\n' : '');
      return { output, exitCode: matches.length > 0 ? 0 : 1 };
    } catch (error) {
      return {
        output: `grep: ${args[1]}: No such file\n`,
        exitCode: 2,
        error: String(error),
      };
    }
  }

  private async handleNode(args: string[]): Promise<CommandResult> {
    if (args.length === 0) {
      return {
        output: 'Node.js REPL - Phase 4 Enhancement\nType: node <file.js> to execute\n',
        exitCode: 0,
      };
    }

    // This is a placeholder - actual execution would require WebContainers or similar
    return {
      output: 'Node.js execution coming soon in Phase 4 enhancement...\n',
      exitCode: 0,
    };
  }

  private async handleNpm(args: string[]): Promise<CommandResult> {
    const command = args[0];

    if (!command) {
      return {
        output: 'npm: missing command\nUsage: npm <install|run|test|...>\n',
        exitCode: 1,
        error: 'Missing command',
      };
    }

    // Placeholder for npm commands
    return {
      output: `npm ${command} - Package management coming in Phase 4 enhancement...\n`,
      exitCode: 0,
    };
  }

  private async handleGit(args: string[]): Promise<CommandResult> {
    const command = args[0];

    if (!command) {
      return {
        output: 'git: missing command\nUsage: git <status|add|commit|push|pull|...>\n',
        exitCode: 1,
        error: 'Missing command',
      };
    }

    // Placeholder for git commands - Phase 3 has GitHub integration
    return {
      output: `git ${command} - Git integration available via GitHub panel\n`,
      exitCode: 0,
    };
  }

  getHistory(): string[] {
    return [...this.commandHistory];
  }

  getPreviousCommand(): string | null {
    if (this.historyIndex > 0) {
      this.historyIndex--;
      return this.commandHistory[this.historyIndex];
    }
    return null;
  }

  getNextCommand(): string | null {
    if (this.historyIndex < this.commandHistory.length - 1) {
      this.historyIndex++;
      return this.commandHistory[this.historyIndex];
    }
    return null;
  }

  getCurrentPath(): string {
    return this.context.currentPath;
  }

  getPrompt(): string {
    return `\x1b[1;32m${this.context.environment.USER}\x1b[0m:\x1b[1;34m${this.context.currentPath}\x1b[0m$ `;
  }
}

/**
 * Production Hardening Middleware
 * Enterprise-grade security and reliability features for ZacAi-Atomic
 * 
 * Features:
 * - Rate limiting (token bucket algorithm)
 * - Request validation and sanitization
 * - Security headers
 * - Error tracking hooks
 * - Health monitoring
 */

import { NextRequest, NextResponse } from 'next/server';
import fs from 'fs';
import path from 'path';

// ============================================================================
// Rate Limiting (In-Memory Token Bucket)
// ============================================================================

interface RateLimitBucket {
  tokens: number;
  lastRefill: number;
}

const rateLimitStore = new Map<string, RateLimitBucket>();

const RATE_LIMITS = {
  // Requests per minute
  chat: { capacity: 20, refillRate: 20 / 60 },      // 20 requests per minute
  api: { capacity: 100, refillRate: 100 / 60 },     // 100 requests per minute
  admin: { capacity: 50, refillRate: 50 / 60 },     // 50 requests per minute
  health: { capacity: 300, refillRate: 300 / 60 },  // 300 requests per minute (monitoring)
};

export function checkRateLimit(
  identifier: string,
  limitType: keyof typeof RATE_LIMITS = 'api'
): { allowed: boolean; remaining: number; resetIn: number } {
  const limit = RATE_LIMITS[limitType];
  const now = Date.now();

  let bucket = rateLimitStore.get(identifier);

  if (!bucket) {
    bucket = { tokens: limit.capacity, lastRefill: now };
    rateLimitStore.set(identifier, bucket);
  }

  // Refill tokens based on time elapsed
  const elapsed = (now - bucket.lastRefill) / 1000; // seconds
  const tokensToAdd = elapsed * limit.refillRate;
  bucket.tokens = Math.min(limit.capacity, bucket.tokens + tokensToAdd);
  bucket.lastRefill = now;

  // Check if request can proceed
  if (bucket.tokens >= 1) {
    bucket.tokens -= 1;
    return {
      allowed: true,
      remaining: Math.floor(bucket.tokens),
      resetIn: Math.ceil((limit.capacity - bucket.tokens) / limit.refillRate),
    };
  }

  return {
    allowed: false,
    remaining: 0,
    resetIn: Math.ceil((1 - bucket.tokens) / limit.refillRate),
  };
}

// ============================================================================
// Security Headers
// ============================================================================

export function addSecurityHeaders(response: NextResponse): NextResponse {
  // Prevent clickjacking
  response.headers.set('X-Frame-Options', 'DENY');

  // Prevent MIME type sniffing
  response.headers.set('X-Content-Type-Options', 'nosniff');

  // Enable XSS protection
  response.headers.set('X-XSS-Protection', '1; mode=block');

  // Strict transport security (HTTPS only)
  response.headers.set('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');

  // Content security policy
  response.headers.set(
    'Content-Security-Policy',
    "default-src 'self'; script-src 'self' 'unsafe-inline' 'unsafe-eval'; style-src 'self' 'unsafe-inline'; img-src 'self' data: https:; font-src 'self' data:; connect-src 'self' https:;"
  );

  // Referrer policy
  response.headers.set('Referrer-Policy', 'strict-origin-when-cross-origin');

  // Permissions policy
  response.headers.set(
    'Permissions-Policy',
    'camera=(), microphone=(), geolocation=(), interest-cohort=()'
  );

  return response;
}

// ============================================================================
// Input Validation and Sanitization
// ============================================================================

export interface ValidationError {
  field: string;
  message: string;
  value?: any;
}

export function validateChatInput(input: any): { valid: boolean; errors: ValidationError[] } {
  const errors: ValidationError[] = [];

  // Check message exists
  if (!input.message || typeof input.message !== 'string') {
    errors.push({ field: 'message', message: 'Message is required and must be a string' });
  } else {
    // Check message length
    if (input.message.length === 0) {
      errors.push({ field: 'message', message: 'Message cannot be empty' });
    }
    if (input.message.length > 10000) {
      errors.push({ field: 'message', message: 'Message exceeds maximum length of 10000 characters', value: input.message.length });
    }

    // Check for null bytes (potential injection)
    if (input.message.includes('\0')) {
      errors.push({ field: 'message', message: 'Invalid characters in message' });
    }
  }

  // Validate session ID if provided
  if (input.sessionId && typeof input.sessionId !== 'string') {
    errors.push({ field: 'sessionId', message: 'Session ID must be a string' });
  }

  // Validate model if provided
  if (input.model && typeof input.model !== 'string') {
    errors.push({ field: 'model', message: 'Model must be a string' });
  }

  return {
    valid: errors.length === 0,
    errors,
  };
}

export function sanitizeHtml(input: string): string {
  return input
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#x27;')
    .replace(/\//g, '&#x2F;');
}

export function sanitizeInput(input: any): any {
  if (typeof input === 'string') {
    return sanitizeHtml(input);
  }

  if (Array.isArray(input)) {
    return input.map(sanitizeInput);
  }

  if (typeof input === 'object' && input !== null) {
    const sanitized: any = {};
    for (const [key, value] of Object.entries(input)) {
      sanitized[key] = sanitizeInput(value);
    }
    return sanitized;
  }

  return input;
}

// ============================================================================
// Error Tracking Hooks (Sentry-compatible)
// ============================================================================

export interface ErrorContext {
  userId?: string;
  sessionId?: string;
  requestId?: string;
  url?: string;
  method?: string;
  userAgent?: string;
  ip?: string;
  timestamp: string;
}

export function captureError(error: Error, context: ErrorContext): void {
  // Log to console in development
  if (process.env.NODE_ENV === 'development') {
    console.error('[ERROR]', {
      message: error.message,
      stack: error.stack,
      context,
    });
  }

  // In production, send to error tracking service (Sentry, etc.)
  if (process.env.SENTRY_DSN && process.env.NODE_ENV === 'production') {
    // TODO: Integrate with Sentry SDK
    // Sentry.captureException(error, { contexts: { custom: context } });
  }

  // Write to error log file
  try {
    const logPath = path.join(process.cwd(), 'data', 'error.log');
    const logEntry = JSON.stringify({
      timestamp: context.timestamp,
      message: error.message,
      stack: error.stack,
      context,
    }) + '\n';

    fs.appendFileSync(logPath, logEntry, 'utf-8');
  } catch (logError) {
    // Best-effort logging; don't throw
    console.error('Failed to write error log:', logError);
  }
}

// ============================================================================
// Request ID Generation
// ============================================================================

export function generateRequestId(): string {
  return `req_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
}

// ============================================================================
// IP Address Extraction
// ============================================================================

export function getClientIp(request: NextRequest): string {
  // Check for forwarded IP (from proxy/load balancer)
  const forwarded = request.headers.get('x-forwarded-for');
  if (forwarded) {
    return forwarded.split(',')[0].trim();
  }

  const cfConnectingIp = request.headers.get('cf-connecting-ip');
  if (cfConnectingIp) {
    return cfConnectingIp;
  }

  const realIp = request.headers.get('x-real-ip');
  if (realIp) {
    return realIp;
  }

  const forwardedHeader = request.headers.get('forwarded');
  if (forwardedHeader) {
    const match = forwardedHeader.match(/for="?([^;,"]+)/i);
    if (match && match[1]) {
      return match[1];
    }
  }

  // Fallback to host information (may be localhost in dev)
  return request.nextUrl.hostname || 'unknown';
}

// ============================================================================
// Middleware Wrapper
// ============================================================================

export interface MiddlewareConfig {
  rateLimit?: keyof typeof RATE_LIMITS;
  validateInput?: boolean;
  sanitizeOutput?: boolean;
  requireAuth?: boolean;
  trackErrors?: boolean;
}

export function withHardening(
  handler: (req: NextRequest, context: any) => Promise<NextResponse>,
  config: MiddlewareConfig = {}
) {
  return async (req: NextRequest, context: any) => {
    const requestId = generateRequestId();
    const clientIp = getClientIp(req);
    const startTime = Date.now();

    try {
      // Rate limiting
      if (config.rateLimit) {
        const rateLimit = checkRateLimit(clientIp, config.rateLimit);

        if (!rateLimit.allowed) {
          const response = NextResponse.json(
            {
              error: 'Rate limit exceeded',
              message: `Too many requests. Please try again in ${rateLimit.resetIn} seconds.`,
              resetIn: rateLimit.resetIn,
            },
            { status: 429 }
          );

          response.headers.set('X-RateLimit-Remaining', '0');
          response.headers.set('X-RateLimit-Reset', String(rateLimit.resetIn));
          response.headers.set('X-Request-Id', requestId);

          return addSecurityHeaders(response);
        }

        // Add rate limit headers to response later
      }

      // Input validation
      if (config.validateInput && req.method === 'POST') {
        try {
          const body = await req.json();
          const validation = validateChatInput(body);

          if (!validation.valid) {
            return NextResponse.json(
              {
                error: 'Validation failed',
                errors: validation.errors,
              },
              { status: 400 }
            );
          }
        } catch (e) {
          return NextResponse.json(
            { error: 'Invalid JSON payload' },
            { status: 400 }
          );
        }
      }

      // Call the actual handler
      const response = await handler(req, context);

      // Add security headers
      const secureResponse = addSecurityHeaders(response);

      // Add request ID
      secureResponse.headers.set('X-Request-Id', requestId);

      // Add processing time
      const processingTime = Date.now() - startTime;
      secureResponse.headers.set('X-Processing-Time-Ms', String(processingTime));

      return secureResponse;

    } catch (error) {
      // Error tracking
      if (config.trackErrors) {
        captureError(error as Error, {
          requestId,
          url: req.url,
          method: req.method,
          ip: clientIp,
          userAgent: req.headers.get('user-agent') || 'unknown',
          timestamp: new Date().toISOString(),
        });
      }

      // Return generic error response
      const response = NextResponse.json(
        {
          error: 'Internal server error',
          message: process.env.NODE_ENV === 'development' ? (error as Error).message : 'An unexpected error occurred',
          requestId,
        },
        { status: 500 }
      );

      response.headers.set('X-Request-Id', requestId);
      return addSecurityHeaders(response);
    }
  };
}

// ============================================================================
// Health Check Utilities
// ============================================================================

export interface HealthStatus {
  status: 'healthy' | 'degraded' | 'unhealthy';
  timestamp: string;
  uptime: number;
  version: string;
  checks: {
    database?: 'pass' | 'fail';
    cache?: 'pass' | 'fail';
    ai?: 'pass' | 'fail';
    storage?: 'pass' | 'fail';
  };
}

export async function getHealthStatus(): Promise<HealthStatus> {
  const checks: HealthStatus['checks'] = {};
  let overallStatus: 'healthy' | 'degraded' | 'unhealthy' = 'healthy';

  // Check storage (file system)
  try {
    const testPath = path.join(process.cwd(), 'data', '.health-check');
    fs.writeFileSync(testPath, 'OK', 'utf-8');
    fs.unlinkSync(testPath);
    checks.storage = 'pass';
  } catch (e) {
    checks.storage = 'fail';
    overallStatus = 'degraded';
  }

  // Check AI system (basic)
  try {
    // Verify key modules can be imported
    checks.ai = 'pass';
  } catch (e) {
    checks.ai = 'fail';
    overallStatus = 'unhealthy';
  }

  return {
    status: overallStatus,
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
    version: process.env.npm_package_version || '1.0.0',
    checks,
  };
}

/**
 * Settings Store - Persistent Storage for All Admin Settings
 * 
 * Provides a centralized store for:
 * - System settings (timezone, location, preferences)
 * - Domain configurations (all 23 knowledge domains)
 * - Model settings (all 13 AI models)
 * - User preferences
 * - Training configurations
 * 
 * Storage: JSON files in /data/settings/ directory
 * Future: Migrate to PostgreSQL/MongoDB for production
 */

import * as fs from 'fs';
import * as path from 'path';

const SETTINGS_DIR = path.join(process.cwd(), 'data', 'settings');

// Ensure settings directory exists
if (!fs.existsSync(SETTINGS_DIR)) {
  fs.mkdirSync(SETTINGS_DIR, { recursive: true });
}

export interface SystemSettings {
  systemName: string;
  timezone: string;
  location: string;
  maxConcurrentRequests: number;
  requestTimeout: number;
  enableLogging: boolean;
  logLevel: 'debug' | 'info' | 'warn' | 'error';
  theme: 'light' | 'dark' | 'system';
  updatedAt: string;
}

export interface DomainSettings {
  enabled: boolean;
  confidenceThreshold: number;
  maxTokens: number;
  temperature: number;
  description: string;
  keywords: string[];
  priority: number;
  updatedAt: string;
}

export interface ModelSettings {
  enabled: boolean;
  type: string;
  parameters: Record<string, any>;
  performance: {
    maxLatency: number;
    cacheEnabled: boolean;
  };
  updatedAt: string;
}

export interface UserSettings {
  id: string;
  name: string;
  email: string;
  role: 'admin' | 'user' | 'system';
  preferences: Record<string, any>;
  createdAt: string;
  updatedAt: string;
}

class SettingsStore {
  private readJSON<T>(filename: string, defaultValue: T): T {
    const filePath = path.join(SETTINGS_DIR, filename);
    try {
      if (fs.existsSync(filePath)) {
        const data = fs.readFileSync(filePath, 'utf-8');
        return JSON.parse(data) as T;
      }
    } catch (error) {
      console.error(`[SettingsStore] Error reading ${filename}:`, error);
    }
    return defaultValue;
  }

  private writeJSON<T>(filename: string, data: T): void {
    const filePath = path.join(SETTINGS_DIR, filename);
    try {
      fs.writeFileSync(filePath, JSON.stringify(data, null, 2), 'utf-8');
    } catch (error) {
      console.error(`[SettingsStore] Error writing ${filename}:`, error);
      throw error;
    }
  }

  // System Settings
  getSystemSettings(): SystemSettings {
    return this.readJSON<SystemSettings>('system.json', {
      systemName: 'ZacAi-Atomic',
      timezone: 'America/New_York',
      location: 'United States',
      maxConcurrentRequests: 10,
      requestTimeout: 30000,
      enableLogging: true,
      logLevel: 'info',
      theme: 'system',
      updatedAt: new Date().toISOString(),
    });
  }

  saveSystemSettings(settings: Partial<SystemSettings>): SystemSettings {
    const current = this.getSystemSettings();
    const updated = {
      ...current,
      ...settings,
      updatedAt: new Date().toISOString(),
    };
    this.writeJSON('system.json', updated);
    return updated;
  }

  // Domain Settings
  getDomainSettings(domainName: string): DomainSettings {
    const allDomains = this.readJSON<Record<string, DomainSettings>>('domains.json', {});
    return allDomains[domainName] || {
      enabled: true,
      confidenceThreshold: 0.6,
      maxTokens: 2048,
      temperature: 0.7,
      description: '',
      keywords: [],
      priority: 5,
      updatedAt: new Date().toISOString(),
    };
  }

  saveDomainSettings(domainName: string, settings: Partial<DomainSettings>): DomainSettings {
    const allDomains = this.readJSON<Record<string, DomainSettings>>('domains.json', {});
    const current = allDomains[domainName] || this.getDomainSettings(domainName);
    const updated = {
      ...current,
      ...settings,
      updatedAt: new Date().toISOString(),
    };
    allDomains[domainName] = updated;
    this.writeJSON('domains.json', allDomains);
    return updated;
  }

  getAllDomains(): Record<string, DomainSettings> {
    return this.readJSON<Record<string, DomainSettings>>('domains.json', {});
  }

  // Model Settings
  getModelSettings(modelName: string): ModelSettings {
    const allModels = this.readJSON<Record<string, ModelSettings>>('models.json', {});
    return allModels[modelName] || {
      enabled: true,
      type: 'inference',
      parameters: {},
      performance: {
        maxLatency: 5000,
        cacheEnabled: true,
      },
      updatedAt: new Date().toISOString(),
    };
  }

  saveModelSettings(modelName: string, settings: Partial<ModelSettings>): ModelSettings {
    const allModels = this.readJSON<Record<string, ModelSettings>>('models.json', {});
    const current = allModels[modelName] || this.getModelSettings(modelName);
    const updated = {
      ...current,
      ...settings,
      updatedAt: new Date().toISOString(),
    };
    allModels[modelName] = updated;
    this.writeJSON('models.json', allModels);
    return updated;
  }

  getAllModels(): Record<string, ModelSettings> {
    return this.readJSON<Record<string, ModelSettings>>('models.json', {});
  }

  // User Settings
  getUser(userId: string): UserSettings | null {
    const allUsers = this.readJSON<Record<string, UserSettings>>('users.json', {});
    return allUsers[userId] || null;
  }

  saveUser(user: UserSettings): UserSettings {
    const allUsers = this.readJSON<Record<string, UserSettings>>('users.json', {});
    const updated = {
      ...user,
      updatedAt: new Date().toISOString(),
    };
    allUsers[user.id] = updated;
    this.writeJSON('users.json', allUsers);
    return updated;
  }

  getAllUsers(): UserSettings[] {
    const allUsers = this.readJSON<Record<string, UserSettings>>('users.json', {});
    return Object.values(allUsers);
  }

  deleteUser(userId: string): boolean {
    const allUsers = this.readJSON<Record<string, UserSettings>>('users.json', {});
    if (allUsers[userId]) {
      delete allUsers[userId];
      this.writeJSON('users.json', allUsers);
      return true;
    }
    return false;
  }
}

export const settingsStore = new SettingsStore();

/**
 * Smart Weights Loader
 * Production-grade weight loading with version selection and fallback logic
 * 
 * Features:
 * - Automatic discovery of latest trained weights
 * - Fallback to pretrained weights if no trained weights available
 * - Version parsing from timestamp suffixes
 * - Caching for performance
 * - Type-safe loading with validation
 */

import fs from 'fs';
import path from 'path';

export interface WeightMetadata {
  domain: string;
  type: 'pretrained' | 'trained';
  version: string;
  timestamp?: string;
  filePath: string;
  exists: boolean;
  sizeBytes?: number;
}

export interface LoadedWeights {
  metadata: WeightMetadata;
  weights: any;
  loadedAt: Date;
  loadTimeMs: number;
}

// Cache for loaded weights
const weightsCache = new Map<string, { weights: any; loadedAt: Date }>();
const CACHE_TTL_MS = 60 * 60 * 1000; // 1 hour

/**
 * Find all weight files for a domain
 */
export function discoverWeights(domainPath: string, domainName: string): WeightMetadata[] {
  const weightsDir = path.join(domainPath, `${domainName}_weights`);

  if (!fs.existsSync(weightsDir)) {
    return [];
  }

  const files = fs.readdirSync(weightsDir);
  const weightFiles: WeightMetadata[] = [];

  // Pattern: <domain>_pretrained_weights.json
  const pretrainedPattern = new RegExp(`^${domainName}_pretrained_weights\\.json$`);

  // Pattern: <domain>_trained_weights_v1_YYYY-MM-DD.json
  const trainedPattern = new RegExp(`^${domainName}_trained_weights_v(\\d+)_(\\d{4}-\\d{2}-\\d{2})\\.json$`);

  files.forEach(file => {
    const filePath = path.join(weightsDir, file);

    // Check pretrained
    if (pretrainedPattern.test(file)) {
      weightFiles.push({
        domain: domainName,
        type: 'pretrained',
        version: '1.0.0',
        filePath,
        exists: fs.existsSync(filePath),
        sizeBytes: fs.existsSync(filePath) ? fs.statSync(filePath).size : 0,
      });
    }

    // Check trained with version
    const trainedMatch = file.match(trainedPattern);
    if (trainedMatch) {
      const [, versionNum, timestamp] = trainedMatch;
      weightFiles.push({
        domain: domainName,
        type: 'trained',
        version: `1.${versionNum}.0`,
        timestamp,
        filePath,
        exists: fs.existsSync(filePath),
        sizeBytes: fs.existsSync(filePath) ? fs.statSync(filePath).size : 0,
      });
    }
  });

  return weightFiles;
}

/**
 * Select best weights to load (prefer latest trained, fallback to pretrained)
 */
export function selectBestWeights(weights: WeightMetadata[]): WeightMetadata | null {
  if (weights.length === 0) return null;

  // Filter only existing files
  const existingWeights = weights.filter(w => w.exists && w.sizeBytes && w.sizeBytes > 0);

  if (existingWeights.length === 0) return null;

  // Separate trained and pretrained
  const trained = existingWeights.filter(w => w.type === 'trained');
  const pretrained = existingWeights.filter(w => w.type === 'pretrained');

  // Prefer latest trained weights
  if (trained.length > 0) {
    // Sort by timestamp descending
    trained.sort((a, b) => {
      if (!a.timestamp || !b.timestamp) return 0;
      return b.timestamp.localeCompare(a.timestamp);
    });
    return trained[0];
  }

  // Fallback to pretrained
  if (pretrained.length > 0) {
    return pretrained[0];
  }

  return null;
}

/**
 * Load weights from file with caching
 */
export function loadWeights(weightMeta: WeightMetadata, useCache: boolean = true): LoadedWeights {
  const startTime = Date.now();
  const cacheKey = weightMeta.filePath;

  // Check cache
  if (useCache && weightsCache.has(cacheKey)) {
    const cached = weightsCache.get(cacheKey)!;
    const age = Date.now() - cached.loadedAt.getTime();

    if (age < CACHE_TTL_MS) {
      return {
        metadata: weightMeta,
        weights: cached.weights,
        loadedAt: cached.loadedAt,
        loadTimeMs: Date.now() - startTime,
      };
    }
  }

  // Load from file
  const weightsData = JSON.parse(fs.readFileSync(weightMeta.filePath, 'utf-8'));

  // Cache it
  if (useCache) {
    weightsCache.set(cacheKey, {
      weights: weightsData,
      loadedAt: new Date(),
    });
  }

  return {
    metadata: weightMeta,
    weights: weightsData,
    loadedAt: new Date(),
    loadTimeMs: Date.now() - startTime,
  };
}

/**
 * Smart loader: auto-discover and load best weights for a domain
 */
export function loadDomainWeights(domainPath: string, domainName: string, useCache: boolean = true): LoadedWeights | null {
  const discovered = discoverWeights(domainPath, domainName);
  const best = selectBestWeights(discovered);

  if (!best) {
    console.warn(`⚠️  No weights found for domain: ${domainName}`);
    return null;
  }

  return loadWeights(best, useCache);
}

/**
 * Clear weights cache (useful for testing/reloading)
 */
export function clearCache(domain?: string) {
  if (domain) {
    // Clear cache for specific domain
    for (const [key] of weightsCache) {
      if (key.includes(domain)) {
        weightsCache.delete(key);
      }
    }
  } else {
    // Clear all cache
    weightsCache.clear();
  }
}

/**
 * Get cache statistics
 */
export function getCacheStats() {
  return {
    entriesCount: weightsCache.size,
    domains: Array.from(weightsCache.keys()).map(k => path.basename(path.dirname(k))),
  };
}

// Export for testing/debugging
export const __testing__ = {
  weightsCache,
  CACHE_TTL_MS,
};

/**
 * File: src/lib/terminalManager.ts
 * Purpose: Manage terminal sessions for dev console
 * Features: Spawn bash shells, manage WebSocket connections, cleanup on disconnect
 */

import type { WebSocket, WebSocketServer } from 'ws';
import * as pty from 'node-pty';
import { logEvent } from './systemActivityLogger.cjs';

export interface TerminalSession {
  id: string;
  pty: pty.IPty;
  ws: WebSocket;
  userId?: string;
  createdAt: Date;
}

const terminals = new Map<string, TerminalSession>();

export function createTerminal(ws: WebSocket, userId?: string): string {
  const id = Math.random().toString(36).substring(7);

  const shell = process.platform === 'win32' ? 'powershell.exe' : 'bash';
  const terminal = pty.spawn(shell, [], {
    name: 'xterm-color',
    cols: 80,
    rows: 30,
    cwd: process.cwd(),
    env: process.env as { [key: string]: string },
  });

  const session: TerminalSession = {
    id,
    pty: terminal,
    ws,
    userId,
    createdAt: new Date(),
  };

  terminals.set(id, session);

  terminal.onData((data: string) => {
    try {
      if (ws.readyState === 1) { // OPEN
        ws.send(JSON.stringify({ type: 'output', data }));
      }
    } catch (error) {
      console.error('Failed to send terminal data:', error);
    }
  });

  terminal.onExit(() => {
    terminals.delete(id);
    try {
      if (ws.readyState === 1) {
        ws.send(JSON.stringify({ type: 'exit' }));
      }
    } catch (error) {
      console.error('Failed to send exit message:', error);
    }
  });

  ws.on('message', (message: any) => {
    try {
      const data = JSON.parse(message.toString());
      if (data.type === 'input') {
        terminal.write(data.data);
      } else if (data.type === 'resize' && data.cols && data.rows) {
        terminal.resize(data.cols, data.rows);
      }
    } catch (error) {
      console.error('Failed to process terminal message:', error);
    }
  });

  ws.on('close', () => {
    terminal.kill();
    terminals.delete(id);
    logEvent('terminal', 'closed', { terminalId: id, userId });
  });

  logEvent('terminal', 'created', { terminalId: id, userId });

  return id;
}

export function getTerminal(id: string): TerminalSession | undefined {
  return terminals.get(id);
}

export function closeTerminal(id: string): void {
  const session = terminals.get(id);
  if (session) {
    session.pty.kill();
    terminals.delete(id);
    logEvent('terminal', 'closed', { terminalId: id });
  }
}

export function closeAllTerminals(): void {
  for (const [id, session] of terminals.entries()) {
    session.pty.kill();
    terminals.delete(id);
  }
  logEvent('terminal', 'all_closed', { count: terminals.size });
}

export function initializeWebSocketServer(wss: WebSocketServer): void {
  wss.on('connection', (ws: WebSocket) => {
    console.log('[Terminal] WebSocket connection established');

    ws.on('message', (message: any) => {
      try {
        const data = JSON.parse(message.toString());

        if (data.type === 'init') {
          const terminalId = createTerminal(ws, data.userId);
          ws.send(JSON.stringify({ 
            type: 'ready', 
            terminalId,
            shell: process.platform === 'win32' ? 'powershell' : 'bash'
          }));
        }
      } catch (error) {
        console.error('[Terminal] Failed to process message:', error);
        ws.send(JSON.stringify({ 
          type: 'error', 
          message: 'Failed to initialize terminal'  
        }));
      }
    });

    ws.on('error', (error: Error) => {
      console.error('[Terminal] WebSocket error:', error);
    });

    ws.on('close', () => {
      console.log('[Terminal] WebSocket connection closed');
    });
  });

  console.log('[Terminal] WebSocket server initialized');
  logEvent('websocket', 'server_initialized', { service: 'terminal' });
}

// Graceful shutdown
process.on('SIGINT', () => {
  console.log('\n[Terminal] Shutting down gracefully...');
  closeAllTerminals();
  process.exit(0);
});

process.on('SIGTERM', () => {
  console.log('\n[Terminal] Shutting down gracefully...');
  closeAllTerminals();
  process.exit(0);
});

// Export terminal manager object for server.ts
export const terminalManager = {
  createTerminal,
  getTerminal,
  closeTerminal,
  closeAllTerminals,
  initializeWebSocketServer,
  initialize: async (server: any) => {
    const ws = await import('ws');
    const wss = new ws.WebSocketServer({ server, path: '/terminal' });
    initializeWebSocketServer(wss);
    console.log('[Terminal] WebSocket server initialized on path /terminal');
  }
};

// Export all functions
export default terminalManager;

/**
 * General utility helpers
 */
export const formatDate = (date: Date): string => {
  return date.toLocaleTimeString("en-US", {
    hour: "2-digit",
    minute: "2-digit",
  })
}

export const generateId = (): string => {
  return `id-${Date.now()}-${Math.random().toString(36).substring(2, 11)}`
}

type DebounceFunction = (...args: unknown[]) => void

export function debounce(func: DebounceFunction, wait: number): DebounceFunction {
  let timeout: ReturnType<typeof setTimeout> | null = null
  return (...args: unknown[]) => {
    if (timeout) clearTimeout(timeout)
    timeout = setTimeout(() => func(...args), wait)
  }
}

type ThrottleFunction = (...args: unknown[]) => void

export function throttle(func: ThrottleFunction, limit: number): ThrottleFunction {
  let inThrottle = false
  return (...args: unknown[]) => {
    if (!inThrottle) {
      func(...args)
      inThrottle = true
      setTimeout(() => (inThrottle = false), limit)
    }
  }
}

export function safeJsonParse(json: string, fallback: any): any {
  try {
    return JSON.parse(json)
  } catch {
    return fallback
  }
}
